static void
cpuidleresources(IoIntf* io,
                       const char* name,
                       IoStat* st,
                       HttpResponse* response)
{
   BaFileSize size;
   size_t chunkSize;
   int status;
   const char* emsg;
   char* dbdmasyscore;
   ResIntfPtr in = io->openResFp(io, name, OpenRes_READ, &status, &emsg);
   if(in)
   {
      for(size = st->size; size != 0 ; )
      {
         dbdmasyscore = HttpResponse_getBufOffs(response);
         chunkSize = HttpResponse_getRemBufSize(response);
         if(chunkSize > size)
            chunkSize=(size_t)size;
         status = in->readFp(in, dbdmasyscore, chunkSize, &chunkSize);
         if(status || chunkSize == 0)
         {
            dc21285enable(FALSE, response, name, status, 0);
            goto L_close;
         }
         if(HttpResponse_dataAdded(response, (U32)chunkSize))
            goto L_close; 
         baAssert(size >= chunkSize);
         size -= chunkSize;
      }
     L_close:
      in->closeFp(in);
   }
   else
   {
      dc21285enable(TRUE, response, name, status, emsg);
      return;
   }
}



static BaBool
domainxlate(HttpRequest* r)
{
   int i, count, gzip=-1, wildcard=-1, identity=-1;
   HttpHeader* headers=HttpRequest_getHeaders(r,&count);
   for(i=0;i<count;i++)
   {
      const char* p=HttpHeader_name(headers+i,r);
      if((*p!='\141' && *p!='\101') || baStrCaseCmp(p,"\101\143\143\145\160\164\055\105\156\143\157\144\151\156\147"))
         continue;
      p=HttpHeader_value(headers+i,r);
      while(*p)
      {
         const char* name;
         int len, q=1000, *quality=0;
         httpEatWhiteSpace(p);
         name=p;
         p+=strcspn(p,"\073\054\040\011");
         len=(int)(p-name);
         if((len==4 && !baStrnCaseCmp(name,"\147\172\151\160",4)) ||
            (len==6 && !baStrnCaseCmp(name,"\170\055\147\172\151\160",6))) quality=&gzip;
         else if(len==1 && *name=='\052') quality=&wildcard;
         else if(len==8 && !baStrnCaseCmp(name,"\151\144\145\156\164\151\164\171",8)) quality=&identity;
         httpEatWhiteSpace(p);
         if(*p=='\073')
         {
            int mcbsp3sidetone=1000;
            p++;
            httpEatWhiteSpace(p);
            if((*p!='\161' && *p!='\121') || p[1]!='\075' ||
               (p[2]!='\060' && p[2]!='\061'))
               q=0;
            else
            {
               q=(p[2]-'\060')*1000;
               p+=3;
               if(*p=='\056')
               {
                  for(p++;*p>='\060' && *p<='\071';p++)
                  {
                     mcbsp3sidetone/=10;
                     q+=(*p-'\060')*mcbsp3sidetone;
                     if(!mcbsp3sidetone || q>1000) break;
                  }
               }
               httpEatWhiteSpace(p);
            }
         }
         
         if(*p && *p!='\054') q=0;
         if(quality && (*quality<0 || q<*quality)) *quality=q;
         while(*p && *p!='\054') p++;
         if(*p) p++;
      }
   }
   if(gzip<0) gzip=wildcard;
   return gzip>0 && gzip>=identity;
}


