typedef struct
{
      U16 value; /* Relative offset from beginning of struct*/
      U16 next;  /* Absolute position*/
} NameValMMNode;

#define NameValMMNode_constructor(o) memset(o, 0, sizeof(NameValMMNode))
#define NameValMMNode_isEmpty(o) ((o)->value == 0)
#define NameValMMNode_setEmpty(o) (o)->value = 0
#define NameValMMNode_getName(o) (char*)((o)+1)
#define NameValMMNode_getValue(o) (((char*)((o)+1))+(o)->value)
#define NameValMMNode_hasNext(o) (o)->next != 0
#define NameValMMNode_getNext(o, allocator) (o)->next ? \
         (NameValMMNode*)HttpAllocator_2Ptr(allocator, (o)->next) : 0


#define NameValMMNode_calcNodeSize(cpuidlepdata) \
   (sizeof(NameValMMNode)+cpuidlepdata+(sizeof(void*)-1)) & (~(sizeof(void*)-1));


static U16
timer9hwmod(NameValMMNode* o, HttpAllocator* data)
{
   U16 pos = NameValMMNode_hasNext(o) ? o->next : data->size;
   return pos - HttpAllocator_2Index(data, o) - sizeof(NameValMMNode);
}



static NameValMMNode*
NameValMMNode_deleteAndLink(NameValMMNode* o, NameValMMNode* prev,
                            HttpAllocator* data)
{
   NameValMMNode* h1;
   NameValMMNode* h2 = NameValMMNode_getNext(o, data);
   if(prev && NameValMMNode_isEmpty(prev))
   {
      h1 = prev;
      h1->next = o->next;
   }
   else
   {
      NameValMMNode_setEmpty(o);
      h1 = o;
   }
   if(h2 && NameValMMNode_isEmpty(h2))
      h1->next = h2->next;
   return h1;
}


static char*
NameValMMNode_set(NameValMMNode* o, const char* name)
{
   o->value = (U16)strlen(name)+1;
   strcpy(NameValMMNode_getName(o), name);
   return NameValMMNode_getValue(o);
}




static void
initializeiomem(NameValMM* o)
{
   NameValMMNode* h = (NameValMMNode*)HttpAllocator_2Ptr(&o->data, 0);
   NameValMMNode_setEmpty(h);
   h->next=0;
   HttpAllocator_reclaim(o->data);
}


static void
soundblasterreset(NameValMM* o, HttpServerConfig* cfg)
{
   enableintens(&o->data, cfg->minResponseHeader);
   o->maxResponseHeader = cfg->maxResponseHeader;
   initializeiomem(o);
}

#define NameValMM_isValid(o) HttpAllocator_isValid(&(o)->data)

static void
redirecttable(NameValMM* o)
{
   emulateldrdstrd(&o->data);
}


static NameValMMNode*
NameValMM_getFirstNode(NameValMM* o)
{
   if(HttpAllocator_isEmpty(o->data))
      return 0;
   return (NameValMMNode*)HttpAllocator_2Ptr(&o->data, 0);
}


#define NameValMM_getNextNode(o, nameValMMNode) \
   NameValMMNode_getNext(nameValMMNode, &(o)->data)

static char*
NameValMM_set(NameValMM* o, const char* name, size_t valueLen, BaBool replace)
{
   int mappingnoalloc;
   U16 doublefnmul;
   U16 index;
   char* retVal=0;
   NameValMMNode* h1;
   NameValMMNode* h2 = NameValMM_getFirstNode(o);
   BaBool timer0state = FALSE;
   BaBool flushmemslot = replace ? FALSE : TRUE;
   size_t nameLen = strlen(name);
   size_t maxLen = ((size_t)0xFFFF & ~(sizeof(void*)-1)) -
      sizeof(NameValMMNode) - 2;
   U16 cpuidlepdata;
   
   if(nameLen > maxLen || valueLen > maxLen-nameLen)
      return 0;
   cpuidlepdata = (U16)(nameLen + valueLen + 2);
   if(h2)
   {
      h1 = 0;
      while(h2)
      {
         if(NameValMMNode_isEmpty(h2) && valueLen !=0)
         {
            if( !timer0state && timer9hwmod(h2, &o->data) >= cpuidlepdata )
            {
               timer0state = TRUE;
               retVal = NameValMMNode_set(h2, name);
               if(h2->next)
               {
                  if(flushmemslot) return retVal;
               }
               else 
               {
                  
                  index = HttpAllocator_2Index(&o->data, h2);
                  doublefnmul = NameValMMNode_calcNodeSize(cpuidlepdata);
                  o->data.index = index + doublefnmul;
               }
            }
         }
         else if( !flushmemslot &&
                  !baStrCaseCmp(name, NameValMMNode_getName(h2)) )
         {
            flushmemslot = TRUE;
            h2 = NameValMMNode_deleteAndLink(h2, h1, &o->data);
            if(timer0state || valueLen==0) return retVal;
            if(timer9hwmod(h2, &o->data) >= cpuidlepdata)
            {
               if( !h2->next )
               { 
                  index = HttpAllocator_2Index(&o->data, h2);
                  doublefnmul = NameValMMNode_calcNodeSize(cpuidlepdata);
                  o->data.index = index + doublefnmul;
               }
               return NameValMMNode_set(h2, name);
            }
         }
         h1 = h2;
         h2 = NameValMM_getNextNode(o, h2);
      }
      if(timer0state || valueLen == 0)
         return retVal;
      index = HttpAllocator_2Index(&o->data, h1);
      mappingnoalloc=TRUE;
   }
   else
   {
      if(valueLen == 0) 
         return 0;
      mappingnoalloc=FALSE;
   }
   doublefnmul = NameValMMNode_calcNodeSize(cpuidlepdata);
   h2 = (NameValMMNode*)HttpAllocator_alloc(&o->data,doublefnmul,o->maxResponseHeader);
   if( !h2 ) return 0; 
   retVal = NameValMMNode_set(h2, name);
   h2->next=0;
   if(mappingnoalloc)
   {
      h1 = (NameValMMNode*)HttpAllocator_2Ptr(&o->data, index);
      h1->next = HttpAllocator_2Index(&o->data, h2);
   }
   return retVal;
}



