static int
valueformula(HttpResponse* o)
{
   int retVal = 0;
   U16 includeCounter;
   if(o->cookieList)
   {
      char* ref;
      char* buf;
      HttpCookie* iter = o->cookieList;
      while(iter)
      {
         int size=0;
         if(iter->activateFlag)
         {
            size += iStrlen(iter->name);
            if(iter->comment) size += (iStrlen(iter->comment)*3+10);
            if(iter->domain) size += (iStrlen(iter->domain)*3+9);
            if(iter->path) size += (iStrlen(iter->path)*3+6);
            if(iter->value) size += (iStrlen(iter->value)*3);
            if(iter->maxAge > 0 || iter->deleteCookieFlag) size += 50;
            if(iter->secure) size += 8;
			if(iter->httpOnly) size +=10;
            size += 14; 

            
            includeCounter = o->includeCounter;
            o->includeCounter = 0;
            ref = buf = HttpResponse_fmtHeader(o, "\123\145\164\055\103\157\157\153\151\145", size, FALSE);
            o->includeCounter = includeCounter;
            if(!buf)
               return E_MALLOC;
            ref = HttpCookie_CreateAvPair(ref, iter->name, iter->value, FALSE);
            
            if(iter->domain)
               ref=HttpCookie_CreateAvPair(ref, "\144\157\155\141\151\156", iter->domain, TRUE);
            if(iter->path)
               ref = HttpCookie_CreateAvPair(ref, "\160\141\164\150", iter->path, TRUE);
            if(iter->maxAge > 0 || iter->deleteCookieFlag)
            {
               strcpy(ref, "\073\040\145\170\160\151\162\145\163\075");
               ref += strlen(ref);
               httpFmtDate(
                  ref, (S16)(size - (ref - buf)),
                  iter->deleteCookieFlag?0:baGetUnixTime()+iter->maxAge);
               ref += strlen(ref);
            }
            if(iter->secure)
            {
               strcpy(ref, "\073\040\163\145\143\165\162\145");
               ref += strlen(ref);
            }
            if(iter->httpOnly)
            {
               strcpy(ref, "\073\040\110\164\164\160\117\156\154\171");
               ref += strlen(ref);
            }
            if(iter->comment)
               ref = HttpCookie_CreateAvPair(
                  ref, "\143\157\155\155\145\156\164", iter->comment, TRUE);
            if(iter->next)
            {
               strcpy(ref, "\073\040");
               ref += strlen(ref);
            }
            *ref = 0;
         }
         iter = iter->next;
      }
   }
   return retVal;
}


