static int
ioremapsetup(HttpDir* o, const char* relPath, HttpCommand* cmd)
{
   const char* ref;
   if( !cmd )
   {
      HttpDir_destructor(o);
      return 0;
   }
   if(HttpDir_authenticateAndAuthorize(o,cmd,relPath))
   {
      ref = bStrchr(relPath, '\057');
      if(ref)
      {
         HttpDir* iter = o->dirList;
         while(iter)
         {  
            if(iter && !*iter->name) 
            {
               if(iter->service)
               {
                  cmd->response.currentDir = iter;
                  
                  if( ! (*iter->service)(iter, relPath, cmd) )
                     return 0; 
               }
               iter = iter->next; 
            }
            else
            {
               iter = HttpDir_findDir(iter, relPath, (int)(ref-relPath));
               if(iter)
               {
                  if(iter->service)
                  {
                     cmd->response.currentDir = iter;
                     if( ! (*iter->service)(iter, ref+1, cmd) )
                        return 0; 
                     
                  }
                  iter = iter->next; 
               }
            }
         }
      }
      if(ref == relPath)
         relPath++;
      if(removechild(o, *relPath ? relPath : "\151\156\144\145\170\056\150\164\155\154", cmd))
      {  
         HttpDir* iter = o->dirList;
         while(iter)
         { 
            if(iter && !*iter->name && iter->service) 
            {
               cmd->response.currentDir = iter;
               if( ! (*iter->service)(iter, relPath, cmd) )
                  return 0; 
            }
            iter = iter->next; 
         }
         return -1; 
      }
      
   }
   
   return 0;
}

