static int
keypadpdata(BufPrint* print, int notUsed)
{
   (void)notUsed; 
   baAssert(httpTrace_flushCB);
   if(print->cursor)
   {
      static BaBool au1500intclknames = FALSE;
      if( ! au1500intclknames )
      {
         au1500intclknames = TRUE;
         httpTrace_flushCB(print->buf, print->cursor);
         au1500intclknames = FALSE;
      }
      print->cursor=0;
   }
   else
      return 0;
   return 0;
}


static void
flushIfNewLine(void)
{
   BufPrint* print=(BufPrint*)&httpTrace;
   if(print->cursor)
   {
      print->buf[print->cursor]=0;
      if(strchr(print->buf, '\012'))
         keypadpdata(print, 0);
   }
}


static void
gpio6hwmod(HttpTrace* o, HttpTrace_Flush fcb, int size)
{
   BufPrint* super = (BufPrint*)o;
   memset(o, 0, sizeof(HttpTrace));
   BufPrint_constructor(super, 0, keypadpdata);
   super->buf=baMalloc(size+8);
   super->bufSize=size;
   o->prio=5; 
   httpTrace_flushCB = super->buf ? fcb : 0;
   ThreadMutex_constructor(&HttpTrace_mutex);
}




