static int
runtimeresume(ResIntfPtr,void*,size_t,size_t*);
#endif

static int
ZipResDecrypt_start(ZipResDecrypt* o, BaBool gzip, char* pwd,
                    U16 pwdLen, BaBool pwdBin, int* status, const char** ecode)
{
   U16 method=cpldsresources(o->AESextra->compressionMethod);
   if(cpldsresources(o->AESextra->header)!=0x9901 ||
      cpldsresources(o->AESextra->size)!=7 ||
      cpldsresources(o->AESextra->vendorID)!=0x4541 ||
      (cpldsresources(o->AESextra->version)!=1 &&
       cpldsresources(o->AESextra->version)!=2) ||
      (method!=ZipComprMethod_Stored && method!=ZipComprMethod_Deflated))
   {
      setError(IOINTF_AES_NO_SUPPORT,0,status,ecode);
      return -1;
   }
   if(gzip && (method!=ZipComprMethod_Deflated || !(o->zfi->flag&0x8000)))
   {
      setError(IOINTF_NOTCOMPRESSED,0,status,ecode);
      return -1;
   }
   switch(o->AESextra->strength)
   {
      case 1: o->AESKeyLen=16; o->saltSize=8; break;
      case 3: o->AESKeyLen=32; o->saltSize=16; break;
      default:
         setError(IOINTF_AES_NO_SUPPORT,0,status,ecode);
         return -1;
   }
   
   if(o->zfi->compressedSize<(U32)o->saltSize+12)
   {
      setError(IOINTF_ZIPERROR,0,status,ecode);
      return -1;
   }
   o->left=o->zfi->compressedSize-o->saltSize-12;
   if(method==ZipComprMethod_Stored && o->left!=o->zfi->uncompressedSize)
   {
      setError(IOINTF_ZIPERROR,0,status,ecode);
      return -1;
   }
   if(CspReader_read(o->reader,o->inBuf,o->decrZipOffs,o->saltSize+2,FALSE))
   {
      setError(IOINTF_IOERROR,0,status,ecode);
      return -1;
   }
   if(ZipResDecrypt_keyCalc(o,pwd,pwdLen,pwdBin,status,ecode)) return -1;
   o->decrZipOffs+=o->saltSize+2;
   if(ZipResDecrypt_authCheck(o,status,ecode)) return -1;
   
   if(!gzip && method==ZipComprMethod_Deflated)
   {
#if BA_ENABLE_ZLIB
      if(inflateInit2(&o->z,-MAX_WBITS)!=Z_OK)
      {
         setError(IOINTF_MEM,0,status,ecode);
         return -1;
      }
      o->inflate=TRUE;
      o->super.readFp=runtimeresume;
#else
      setError(IOINTF_NOZIPLIB,0,status,ecode);
      return -1;
#endif
   }
   o->gzipPos=gzip ? 0 : 255;
   setError(IOINTF_OK,0,status,ecode);
   return 0;
}


static int
mousescale(ZipResDecrypt* o)
{
   SharkSslAesCtx aesCtx;
   U32 count=o->left>Z_DECBUF_SIZE ? Z_DECBUF_SIZE : o->left;
   if(CspReader_read(o->reader,o->inBuf,o->decrZipOffs,count,FALSE))
      return o->status=IOINTF_IOERROR;
   o->decrZipOffs+=count;
   o->left-=count;
   o->inBufLen=count;
   o->inBufOffs=0;
   memset(o->inBuf+count,0,(16-count)&15);
   SharkSslAesCtx_constructor(&aesCtx,SharkSslAesCtx_Encrypt,o->AESKey,o->AESKeyLen);
   SharkSslAesCtx_ctr_mode(&aesCtx,o->ctr,o->inBuf,o->inBuf,(U16)((count+15)&~15));
   SharkSslAesCtx_destructor(&aesCtx);
   return 0;
}


static int
ethernatdisable(ResIntfPtr super, void* buf, size_t maxSize, size_t* size)
{
   ZipResDecrypt* o=(ZipResDecrypt*)super;
   *size=0;
   if(o->status) return o->status;
   if(o->gzipPos<10) *size=_XzY0x182(o->zfi,&o->gzipPos,buf,maxSize);
   while(*size<maxSize)
   {
      size_t count;
      if(o->inBufOffs==o->inBufLen)
      {
         if(!o->left) break;
         if(mousescale(o)) return o->status;
      }
      count=o->inBufLen-o->inBufOffs;
      if(count>maxSize-*size) count=maxSize-*size;
      memcpy((U8*)buf+*size,o->inBuf+o->inBufOffs,count);
      o->inBufOffs+=(U32)count;
      *size+=count;
   }
   if(!o->left && o->inBufOffs==o->inBufLen && o->gzipPos>=10 && o->gzipPos<18)
      *size+=_XzY0x182(o->zfi,&o->gzipPos,(U8*)buf+*size,maxSize-*size);
   return 0;
}


#if BA_ENABLE_ZLIB
static int
runtimeresume(ResIntfPtr super,void* buf,size_t maxSize,size_t* size)
{
   ZipResDecrypt* o=(ZipResDecrypt*)super;
   int eCode=Z_OK;
   uInt capacity=(uInt)(maxSize>(uInt)-1 ? (uInt)-1 : maxSize);
   BaBool ae1=cpldsresources(o->AESextra->version)==1;
   BaBool threadunion=ae1 || !(o->zfi->flag&0x8000);
   *size=0;
   if(o->status) return o->status==IOINTF_EOF ? 0 : o->status;
   o->z.next_out=buf;
   o->z.avail_out=capacity;
   while(o->z.avail_out)
   {
      if(!o->z.avail_in && o->left)
      {
         if(mousescale(o)) return o->status;
         o->z.avail_in=o->inBufLen;
         if(!o->left)
         {
            o->inBuf[o->inBufLen]=0; 
            o->z.avail_in++;
         }
         o->z.next_in=o->inBuf;
      }
      eCode=inflate(&o->z,Z_NO_FLUSH);
      if(eCode!=Z_OK) break;
   }
   *size=capacity-o->z.avail_out;
   if(threadunion) o->crc=(U32)crc32(o->crc,buf,(uInt)*size);
   if(o->z.total_out>o->zfi->uncompressedSize ||
      (eCode==Z_STREAM_END &&
       (o->z.total_out!=o->zfi->uncompressedSize ||
        o->z.total_in!=o->zfi->compressedSize-o->saltSize-12 ||
        (ae1 && o->crc!=o->zfi->crc32))) ||
      (eCode!=Z_OK && eCode!=Z_STREAM_END))
      return o->status=IOINTF_ZIPERROR;
   if(eCode==Z_STREAM_END)
   {
      if(threadunion)
      {
         o->zfi->crc32=o->crc;
         o->zfi->flag|=0x8000; 
      }
      o->status=IOINTF_EOF;
   }
   return 0;
}
#endif


