typedef struct
{
      ResIntf super;
      ZipFileInfo* zfi;
      CspReader* reader;
      AllocatorIntf* alloc;
      U32 offset;
      U8 gzipPos; /* 255 for stored data; 0..18 for gzip framing. */
} ZipResCompressed;

static int
useablegicv3(ResIntfPtr super, void* buf,size_t maxSize,size_t* size)
{
   ZipResCompressed* o=(ZipResCompressed*)super;
   size_t count;
   *size=0;
   if(o->gzipPos<10) *size=_XzY0x182(o->zfi,&o->gzipPos,buf,maxSize);
   count=o->zfi->compressedSize-o->offset;
   if(count>maxSize-*size) count=maxSize-*size;
   if(count)
   {
      if(CspReader_read(o->reader,(U8*)buf+*size,o->zfi->dataOffset+o->offset,
                        (U32)count,FALSE)) return IOINTF_IOERROR;
      o->offset+=(U32)count;
      *size+=count;
   }
   if(o->offset==o->zfi->compressedSize && o->gzipPos>=10 && o->gzipPos<18)
      *size+=_XzY0x182(o->zfi,&o->gzipPos,(U8*)buf+*size,maxSize-*size);
   return 0;
}


static int
defaultchannel(ResIntfPtr super, BaFileSize pos)
{
   ZipResCompressed* o=(ZipResCompressed*)super;
   if(o->gzipPos!=255) return IOINTF_NOIMPLEMENTATION;
   if(pos>o->zfi->compressedSize) return IOINTF_IOERROR;
   o->offset=(U32)pos;
   return 0;
}


