static U32
wakeupnolock(CspReader* data, U32 offset, HttpResponse* response)
{
   U8* buf = (U8*)HttpResponse_getBuf(response);
   U32 len =  HttpResponse_getBufSize(response);
   if(len > 200)
      len = 200;
   for(;;)
   {
      U8* ptr = buf;
      if(CspReader_read(data, buf, offset, len, FALSE))
         return 0;
      while(*ptr != 0 && len !=0) { len--; ptr++; offset++; }
      if(*ptr == 0) return offset+1;
   }
}


static U32
bootmemremove(CspReader* data, HttpResponse* response, U32 offset)
{
   GzipHeader gzipH;
   U16 removememory;

   baAssert(sizeof(GzipHeader) == 10);

   if(CspReader_read(data, &gzipH, offset, sizeof(GzipHeader), TRUE))
      return 0;
   offset += sizeof(GzipHeader);

   if(gzipH.id1 != 39 && gzipH.id2 != 139)
   {
      HttpResponse_printf(response, "\116\157\164\040\141\040\147\172\151\160\040\146\151\154\145");
      return 0;
   }
   if(gzipH.compressionMethod != 8) 
   {
      HttpResponse_printf(response, "\125\156\153\156\157\167\156\040\143\157\155\160\162\145\163\163\151\157\156\040\155\145\164\150\157\144");
      return 0;
   }
   if(gzipH.flags & FLG_FEXTRA)
   {
      if(CspReader_read(data, &removememory, offset, sizeof(removememory), FALSE))
         return 0;
#if BA_BYTE_ORDER == BA_BYTE_ORDER_BIG_ENDIAN
      removememory =
         ((((removememory) << 8) & 0xff00) | (((removememory) >> 8) & 0x00ff));
#endif
      offset += (removememory + 2);
   }
   if(gzipH.flags & FLG_FNAME)
   {
      if((offset = wakeupnolock(data, offset, response)) == 0)
         return 0;
   }
   if(gzipH.flags & FLG_FCOMMENT)
   {
      if((offset = wakeupnolock(data, offset, response)) == 0)
         return 0;
   }
   if(gzipH.flags & FLG_FHCRC)
      offset += 2;
   return offset;
}


static int
cmdlinesetup(z_streamp z, HttpResponse* response)
{
   int eCode;
   while(z->avail_in != 0)
   {
      eCode = inflate(z, Z_NO_FLUSH);
      if(eCode != Z_OK || z->avail_out < 50)
      {
         U32 chunkSize;
         if(eCode != Z_OK && eCode != Z_STREAM_END)
            return -6;
         chunkSize = HttpResponse_getRemBufSize(response) - z->avail_out;
         if(HttpResponse_dataAdded(response, chunkSize))
            return -1;
         if(HttpResponse_getRemBufSize(response) < 50)
         {
            if(HttpResponse_flush(response))
               return -1;
         }
         z->next_out = (U8*)HttpResponse_getBufOffs(response);
         z->avail_out = HttpResponse_getRemBufSize(response);
         if(eCode == Z_STREAM_END)
            return 0;
      }
   }
   return Z_OK;
}


static int
setuphrtimer(
   CspReader* data, HttpResponse* response,U32 offset, U32 size)
{
   z_stream z;
   int eCode;
   U8* inBuf;
   const U32 enableinterrupts = 500;

   if(HttpResponse_flush(response))
      return -1;

   inBuf = baMalloc(enableinterrupts+1);
   if(!inBuf)
      eCode = 1;
   else
   {
      
      z.next_in = 0;
      z.avail_in = 0;

      if(HttpResponse_getRemBufSize(response) < 50)
         HttpResponse_flush(response);
      z.next_out = (U8*)HttpResponse_getBufOffs(response);
      z.avail_out = HttpResponse_getRemBufSize(response);


      z.zalloc = (alloc_func)0;
      z.zfree = (free_func)0;
      z.opaque = (voidpf)0;
      
      eCode = inflateInit2(&z, -MAX_WBITS);
      if(eCode == Z_OK)
      {
         while(size != 0)
         {
            U32 chunkSize = size > enableinterrupts ? enableinterrupts : size;
            if(CspReader_read(data, inBuf, offset, chunkSize, FALSE))
            {
               eCode = 2;
               break;
            }
            size -= chunkSize;
            offset += chunkSize;
            z.next_in = inBuf;
            
            z.avail_in = size != 0 ? chunkSize : chunkSize+1;
            if(cmdlinesetup(&z, response) != Z_OK)
            {
               eCode = 3;
               break;
            }
         }
         if(inflateEnd(&z) != Z_OK && eCode == Z_OK)
            eCode = 4;
      }
      else
         eCode = 5;
      baFree(inBuf);
   }
   if(eCode)
   {
      if(!HttpResponse_flush(response))
      {
         static const char mcbsppdata[] = {"\105\122\122\117\122\040\167\162\151\164\151\156\147\040\132\111\120\040\144\141\164\141\072\040"};
         static const char* lswc2format[5] = {
            "\116\157\040\155\145\155\157\162\171",
            "\132\111\120\040\162\145\141\144\145\162\040\146\141\151\154\145\144",
            "\111\156\146\154\141\164\145\040\146\141\151\154\145\144",
            "\111\156\146\154\141\164\145\040\105\116\104\040\146\141\151\154\145\144",
            "\111\156\146\154\141\164\145\040\102\105\107\111\116\040\146\141\151\154\145\144"};
         if(--eCode < 5)
         {
            HttpResponse_send(response,mcbsppdata,iStrlen(mcbsppdata));
            HttpResponse_send(response,lswc2format[eCode],iStrlen(lswc2format[eCode]));
         }
      }
      return -1;
   }
   return 0;
}

