typedef struct
{
      char* username;
      char* passwd;
      U8 buf[80];
} ParseBasicHeader;


static void
patchvector(ParseBasicHeader* o, const char* rtcmatch2clockdev)
{
   int len;
   BaBool overflow;
   o->username = 0;
   o->passwd = 0;

   
   if(baStrnCaseCmp(rtcmatch2clockdev, "\102\141\163\151\143\040", 6))
      return; 

   rtcmatch2clockdev+=6;
   
   len=baB64Decode(o->buf, sizeof(o->buf)-1, rtcmatch2clockdev, &overflow);
   if(overflow)
      return;
   o->buf[len]=0;
   o->passwd = bStrchr((char*)o->buf, '\072');
   if(o->passwd)
   {
      *o->passwd++ = 0;
      o->username = (char*)o->buf;
   }
}

#define ParseBasicHeader_isValid(o) ((o)->username && (o)->passwd)


static int
mfptimerdisable(
   ParseBasicHeader* o, const char* realm, AuthInfo* info)
{
   switch(info->ct)
   {
      case AuthInfoCT_Valid:
         info->password[0]='\077';
         info->password[1]=0;
         return TRUE; 

      case AuthInfoCT_Password:
         if( *info->password && ! strcmp((char*)info->password,o->passwd) )
            return TRUE; 
         break;

      case AuthInfoCT_HA1:
      {
         U8 hexbuf[33];
         calculateHA1Hex(realm,o->username,o->passwd,hexbuf);
         if( ! memcmp(info->password,hexbuf,32) )
            return TRUE; 
      }

      case AuthInfoCT_Invalid: 
         break;
   }
     
   return FALSE; 
}








