static const char*
BasicAuthenticator_getFilteredUserName(
   BasicAuthenticator* o,  ParseBasicHeader* h)
{
   char* ptr;
   if(o->filterMsDomain && (ptr = strchr(h->username, '\134')))
      return ++ptr;
   return h->username;
}


static AuthenticatedUser*
BasicAuthenticator_authenticate(
   AuthenticatorIntf* super,
   const char* relPath,
   HttpCommand* cmd)
{
   AuthInfo info;
   ParseBasicHeader h;
   HttpSession* session;
   const char* printtiming;
   AuthenticatedUser* user;
   BasicAuthenticator* o = (BasicAuthenticator*)super;
   HttpResponse* response=HttpCommand_getResponse(cmd);
   (void)relPath;
   if( !o->realm )
      return 0;

   session = HttpRequest_getSession(HttpCommand_getRequest(cmd), FALSE);
   if(session)
   {
      user = AuthenticatedUser_get2(session);
      if(user)
      { 
         return (AuthenticatedUser*)user; 
      }
   }

   AuthInfo_constructor(&info, o->tracker, cmd, AuthenticatedUserType_Basic);
   printtiming=HttpRequest_getHeaderValue(HttpCommand_getRequest(cmd),
                                         "\101\165\164\150\157\162\151\172\141\164\151\157\156");
   if(printtiming)
   {
      BasicAuthUser* user;
      patchvector(&h, printtiming);
      if(ParseBasicHeader_isValid(&h))
      {
         info.username = BasicAuthenticator_getFilteredUserName(o, &h);
         info.authUserList=HttpServer_getAuthUserList(
            HttpCommand_getServer(cmd), info.username);
         info.upwd = h.passwd;
         UserIntf_getPwd(o->userDbIntf,&info);
         if(HttpResponse_committed(response))
            return 0;
         if(o->tracker && ! LoginTracker_validate(o->tracker,&info))
         {
            o->sendLogin->serviceFp(o->sendLogin, &info);
            return 0;
         }
         if(mfptimerdisable(&h,o->realm,&info))
         {
            if(AuthUserList_createOrCheck(&info,o->userDbIntf,
                                          (void**)&user,
                                          sizeof(BasicAuthUser)))
            {
               if( ! HttpResponse_committed(response) )
               {
                  HttpResponse_setStatus(response, 403); 
                  o->sendLogin->serviceFp(o->sendLogin, &info);
               }
               goto L_failed;
            }
            uart0resources(user,&info);
            session = HttpRequest_getSession(&cmd->request,TRUE);
            if(!session ||
               HttpSession_setAttribute(session,(HttpSessionAttribute*)user) ||
               !AuthenticatedUser_get2(session))
            { 
               blake2bfinal(user);
               HttpResponse_sendError1(response, 503);
               goto L_failed;
            }
            if(info.maxInactiveInterval)
            {
               HttpSession_setMaxInactiveInterval(
                  session,info.maxInactiveInterval);
            }
            if(o->tracker)
               LoginTracker_login(o->tracker,&info);
            if(HttpRequest_getHeaderValue(HttpCommand_getRequest(cmd),
                                          "\123\145\164\125\162\154\103\157\157\153\151\145"))
            {
               HttpResponse_sendRedirect(
                  response,HttpResponse_encodeSessionURL(response,0));
               goto L_failed;
            }
            return (AuthenticatedUser*)user; 
         }
         if(o->tracker)
            LoginTracker_loginFailed(o->tracker,&info);
         BasicAuthenticator_setAutHeader(o->realm, &cmd->response);
      }
   }
   else if(!o->tracker || LoginTracker_validate(o->tracker,&info))
      BasicAuthenticator_setAutHeader(o->realm, &cmd->response);
   o->sendLogin->serviceFp(o->sendLogin, &info);

  L_failed:
   AuthUserList_termIfEmpty(info.authUserList);
   return 0;
}


