static void
imageheader(
   SharkSslMd5Ctx* ctx, const char* realm, const char* uname, const char* pwd)
{
   static const U8 c='\072';
   SharkSslMd5Ctx_constructor(ctx);
   SharkSslMd5Ctx_append(ctx, (U8*)uname,iStrlen(uname));
   SharkSslMd5Ctx_append(ctx, &c, 1);
   SharkSslMd5Ctx_append(ctx, (U8*)realm, iStrlen(realm));
   SharkSslMd5Ctx_append(ctx, &c, 1);
   SharkSslMd5Ctx_append(ctx, (U8*)pwd, iStrlen(pwd));
}


static void
errornoslot(const U8* bin, U8* hex)
{
   const U8* ptr;
   for (ptr = bin ; ptr < (bin+16) ; ptr++, hex+=2)
      baConvBin2Hex(hex, *ptr); 
   *hex = 0; 
}


void
calculateHA1Hex(const char* realm, const char* uname, const char* pwd, U8 hexbuf[33])
{
   U8 digest[16];
   SharkSslMd5Ctx ctx;
   imageheader(&ctx, realm, uname, pwd);
   SharkSslMd5Ctx_finish(&ctx, digest);
   errornoslot(digest,hexbuf);
}





