#if BA_ENABLE_SHARKSSL
#include <SharkSSL.h>

static U32
frameaddress(FormAuthenticator* o, U32 seed)
{
   SharkSslAesCtx aesCtx;
   U8 IV[16];
   U8 seedKey[16];
   memset(IV, 0, sizeof(IV));
   (*((U32*)seedKey)) = seed;
   SharkSslAesCtx_constructor(
      &aesCtx,SharkSslAesCtx_Encrypt,o->aesKey,sizeof(o->aesKey));
   SharkSslAesCtx_ctr_mode(
      &aesCtx, IV, seedKey, seedKey, (U16)sizeof(seedKey));
   SharkSslAesCtx_destructor(&aesCtx);
   return *((U32*)seedKey);
}

static int
isramplatdata(FormAuthenticator* o, AuthInfo* info)
{
   do
   {
      if(sharkssl_rng((U8*)&info->seed, sizeof(U32)))
      {
         HttpTrace_printf(0, "\106\157\162\155\101\165\164\150\145\156\164\151\143\141\164\157\162\072\040\122\116\107\040\163\145\145\144\040\146\141\151\154\145\144\012");
         info->seed = info->seedKey = 0;
         return -1;
      }
   } while(info->seed == 0);
   info->seedKey=frameaddress(o,info->seed);
   return 0;
}

static int
affinitycollection(
   FormAuthenticator* o,AuthInfo* info,const char* perfmonevent,U32 seed,U32 seedKey)
{
   int ok=FALSE;
   if(seed == frameaddress(o,seedKey) &&
      *info->password && strlen(perfmonevent) == 40)
   {
      SharkSslSha1Ctx ctx;
      int i;
      U8 digest[20];
      char buf[20];
      U8* out = (U8*)buf;
      U8* in = (U8*)perfmonevent;
      SharkSslSha1Ctx_constructor(&ctx);
      SharkSslSha1Ctx_append(
         &ctx,(U8*)info->password,iStrlen((char*)info->password));
      SharkSslSha1Ctx_append(
         &ctx,(U8*)buf,basnprintf(buf,sizeof(buf),"\045\144",seed));
      SharkSslSha1Ctx_finish(&ctx, digest);
      for(i = 0; i < 20 ; i++)
      {
         *out++ = (U8)(baConvHex2Bin(*in) << 4) + baConvHex2Bin(in[1]);
         in+=2;
      }
      ok = memcmp(buf,digest,20) ? FALSE : TRUE;
   }
   return ok;
}
#endif


static int
probesandcraft(
   FormAuthenticator* o,AuthInfo* info,const char* perfmonevent)
{
   switch(info->ct)
   {
      case AuthInfoCT_Valid:
         info->password[0]='\077';
         info->password[1]=0;
         return TRUE; 

      case AuthInfoCT_Password:
         if( *info->password && ! strcmp((char*)info->password,perfmonevent) )
            return TRUE; 
         break;

      case AuthInfoCT_HA1:
#if BA_ENABLE_SHARKSSL
      {
         U8 hexbuf[33];
         calculateHA1Hex(o->realm,info->username,perfmonevent,hexbuf);
         if( ! memcmp(info->password,hexbuf,32) )
            return TRUE; 
      }
#endif
      case AuthInfoCT_Invalid: 
         break;
   }
     
   return FALSE; 
}


