#define JDBuf_reset(o) do {                     \
      (o)->index=0;                             \
   } while(0)

#define JDBuf_expandIfNeeded(o, neededSize)                     \
   ((o)->index+neededSize) > (o)->size && JDBuf_expand(o)


#define JDBuf_destructor(o) do {                                    \
      if((o)->buf) { AllocatorIntf_free((o)->alloc, (o)->buf);(o)->buf=0; } \
   }while(0)


static void
pcsxxstatus1(JDBuf* o, AllocatorIntf* alloc)
{
   memset(o,0,sizeof(JDBuf));
   o->alloc=alloc;
}


static int
JDBuf_expand(JDBuf* o)
{
   
   size_t expandSize = 256;
   if( ! o->alloc )
      return -1;
   if(o->buf)
   {
      U8* ptr;
      o->size += expandSize;
      ptr = AllocatorIntf_realloc(o->alloc, o->buf, &o->size);
      if(ptr)
      {
         o->buf = ptr;
         return 0;
      }
      AllocatorIntf_free(o->alloc, o->buf);
   }
   else
   {
      o->buf = AllocatorIntf_malloc(o->alloc, &expandSize);
      if(o->buf)
      {
         o->size = expandSize;
         return 0;
      }
   }
   o->buf=0;
   o->size=0;
   o->index=0;
   return -1;
}






static void
wbinvrange(JLexer* o, JParserVal* v)
{
   v->v.s = (char*)o->asmB->buf;
   v->stringLen = o->asmB->index;
   v->t = JParserT_String;
}


static void
setuppercpu(JLexer* o, JParserVal* v)
{
   JDBuf* asmB = o->asmB;
   baAssert(asmB->buf);
   if(o->isDouble)
   {
      v->v.f=atof((char*)asmB->buf);
      v->t=JParserT_Double;
      if(o->sn)
         v->v.f = -v->v.f;
   }
   else
   {
      v->t = JParserT_Int;
      if(asmB->index > 9)
      {
         S64 l = S64_atoll((char*)asmB->buf);
         S32 lsw = (S32)l;
         if((0xFFFFFFFF00000000LL & l) || (lsw < 0))
         {
             v->v.l = o->sn ? -l : l;
             v->t=JParserT_Long;
         }
         else
            v->v.d = (S32)l;
      }
      else
         v->v.d = (S32)U32_atoi((char*)asmB->buf);
      if(v->t == JParserT_Int && o->sn)
            v->v.d = -v->v.d;
   }
   o->isDouble=0;
}



static int
omap2pwrdm(JLexer* o, JLexerT t, JParserVal* v)
{
   switch(t)
   {
      case JLexerT_Null:
         v->t = JParserT_Null;
         break;
      case JLexerT_Boolean:
         v->t = JParserT_Boolean;
         v->v.b = o->sn;
         break;
      case JLexerT_Number:
         setuppercpu(o,v);
         break;
      case JLexerT_String:
         wbinvrange(o,v);
         break;
      default:
         return -1;
   }
   JDBuf_reset(o->asmB);
   return 0;
}



#define  JLexer_constructor(o, asmBM) do { \
   (o)->asmB = asmBM; \
   (o)->state=JLexerSt_GetNextToken; \
} while(0)



#define JLexer_setBuf(o, buf, size) do {\
   (o)->tokenPtr=(o)->bufStart=buf;\
   (o)->bufEnd=(o)->bufStart+size;\
}while(0)


static BaBool
writeguest(JLexer* o)
{
   while(o->tokenPtr != o->bufEnd)
   {
      baAssert(o->tokenPtr <  o->bufEnd);
      if( ! bIsspace(*o->tokenPtr) )
         return TRUE;
      o->tokenPtr++;
   }
   return FALSE;
}


static int
JLexer_putUtf8(JLexer* o, U32 unicode)
{
   JDBuf* asmB=o->asmB;
   if(JDBuf_expandIfNeeded(asmB,4))
      return -1;
   if(unicode < 0x80)
      asmB->buf[asmB->index++]=(U8)unicode;
   else if(unicode < 0x800)
   {
      asmB->buf[asmB->index++]=(U8)(0xc0|(unicode >> 6));
      asmB->buf[asmB->index++]=(U8)(0x80|(unicode & 0x3f));
   }
   else if(unicode < 0x10000)
   {
      asmB->buf[asmB->index++]=(U8)(0xe0|(unicode >> 12));
      asmB->buf[asmB->index++]=(U8)(0x80|((unicode >> 6)&0x3f));
      asmB->buf[asmB->index++]=(U8)(0x80|(unicode & 0x3f));
   }
   else
   {
      asmB->buf[asmB->index++]=(U8)(0xf0|(unicode >> 18));
      asmB->buf[asmB->index++]=(U8)(0x80|((unicode >> 12)&0x3f));
      asmB->buf[asmB->index++]=(U8)(0x80|((unicode >> 6)&0x3f));
      asmB->buf[asmB->index++]=(U8)(0x80|(unicode & 0x3f));
   }
   return 0;
}


static JLexerT
processorstate(JLexer* o)
{
   JDBuf* asmB = o->asmB;
   for(;;)
   {
      baAssert(o->tokenPtr <=  o->bufEnd);
      if(o->tokenPtr == o->bufEnd)
         return JLexerT_NeedMoreData;

      switch(o->state)
      {
         case JLexerSt_StartComment:
            if(*o->tokenPtr == '\052')
               o->state = JLexerSt_EatComment;
            else if(*o->tokenPtr == '\057')
               o->state = JLexerSt_EatCppComment;
            else
               return JLexerT_ParseErr;
            o->tokenPtr++;
            break;

         case JLexerSt_EatComment:
            while(*o->tokenPtr++ != '\052')
            {
               if(o->tokenPtr == o->bufEnd)
                  return JLexerT_NeedMoreData;
            }
            o->state = JLexerSt_EndComment;
            break;

         case JLexerSt_EndComment:
            if(*o->tokenPtr++ != '\057')
               o->state = JLexerSt_EatComment;
            else
               o->state = JLexerSt_GetNextToken;
            break;

         case JLexerSt_EatCppComment:
            while(*o->tokenPtr++ != '\012')
            {
               if(o->tokenPtr == o->bufEnd)
                  return JLexerT_NeedMoreData;
            }
            o->state = JLexerSt_GetNextToken;
            break;

         case JLexerSt_TrueFalseNull:
            if(bTolower(*o->tokenPtr++) != *o->typeChkPtr++)
               return JLexerT_ParseErr;
            if( ! *o->typeChkPtr )
            {
               o->state = JLexerSt_GetNextToken;
               return (JLexerT)o->retVal;
            }
            break;

         case JLexerSt_String:
            if(JDBuf_expandIfNeeded(o->asmB, 2)) return JLexerT_MemErr;
            for(;;)
            {
               U8 c=*o->tokenPtr;
               if(c == '\134')
               {
                  o->tokenPtr++;
                  o->state = JLexerSt_StringEscape;
                  break;
               }
               if(c == o->sn) 
               {
                  asmB->buf[asmB->index]=0;
                  o->tokenPtr++;
                  o->state = JLexerSt_GetNextToken;
                  return JLexerT_String;
               }
               if(c < 0x20)
                  return JLexerT_ParseErr;
               if(c >= 0x80)
               {
                  if(c >= 0xc2 && c <= 0xdf)
                  {
                     o->unicode=c&0x1f;
                     o->utf8Len=2;
                  }
                  else if(c >= 0xe0 && c <= 0xef)
                  {
                     o->unicode=c&0x0f;
                     o->utf8Len=3;
                  }
                  else if(c >= 0xf0 && c <= 0xf4)
                  {
                     o->unicode=c&0x07;
                     o->utf8Len=4;
                  }
                  else
                     return JLexerT_ParseErr;
                  o->unicodeShift=(S16)(o->utf8Len-1);
                  asmB->buf[asmB->index++]=c;
                  o->tokenPtr++;
                  o->state=JLexerSt_StringUtf8;
                  break;
               }
               asmB->buf[asmB->index++] = c;
               o->tokenPtr++;
               if(JDBuf_expandIfNeeded(o->asmB, 1)) return JLexerT_MemErr;
               if(o->tokenPtr == o->bufEnd)
                  return JLexerT_NeedMoreData;
            }
            break;

         case JLexerSt_StringEscape:
            switch(*o->tokenPtr)
            {
               case '\042':
               case '\057':
               case '\134':
               case '\142':
               case '\146':
               case '\156':
               case '\162':
               case '\164':
                  switch(*o->tokenPtr)
                  {
                     case '\042':  asmB->buf[asmB->index]='\042';  break;
                     case '\057':  asmB->buf[asmB->index]='\057';  break;
                     case '\134': asmB->buf[asmB->index]='\134'; break;
                     case '\142':  asmB->buf[asmB->index]='\010'; break;
                     case '\146':  asmB->buf[asmB->index]='\014'; break;
                     case '\156':  asmB->buf[asmB->index]='\012'; break;
                     case '\162':  asmB->buf[asmB->index]='\015'; break;
                     case '\164':  asmB->buf[asmB->index]='\011'; break;
                  }
                  asmB->index++;
                  o->tokenPtr++;
                  o->state = JLexerSt_String;
                  break;

               case '\165':
                  o->tokenPtr++;
                  o->state = JLexerSt_StringUnicode;
                  o->unicode=0;
                  o->unicodeShift=12;
                  break;

               default:
                     return JLexerT_ParseErr;
            }
            break;

         case JLexerSt_StringUnicode:
         {
            U32 hex;
            char c = *o->tokenPtr;
            if ( c >= '\060' && c <= '\071' )
               hex = c - '\060';
            else if ( c >= '\141' && c <= '\146' )
               hex = c - '\141' + 10;
            else if ( c >= '\101' && c <= '\106' )
               hex = c - '\101' + 10;
            else
               return JLexerT_ParseErr;
            o->unicode |= (hex << o->unicodeShift);
            o->tokenPtr++;
            baAssert(o->unicodeShift >= 0);
            if( ! o->unicodeShift )
            {
               if(o->surrogate)
               {
                  if(o->unicode < 0xdc00 || o->unicode > 0xdfff)
                     return JLexerT_ParseErr;
                  o->unicode=0x10000+
                     (((U32)o->surrogate-0xd800)<<10)+
                     (o->unicode-0xdc00);
                  o->surrogate=0;
               }
               else if(o->unicode >= 0xd800 && o->unicode <= 0xdbff)
               {
                  o->surrogate=(U16)o->unicode;
                  o->state=JLexerSt_StringSurrogateEscape;
                  break;
               }
               else if(o->unicode >= 0xdc00 && o->unicode <= 0xdfff)
                  return JLexerT_ParseErr;
               if(JLexer_putUtf8(o,o->unicode))
                  return JLexerT_MemErr;
               o->state = JLexerSt_String;
            }
            else
               o->unicodeShift -= 4;
            break;
         }

         case JLexerSt_StringSurrogateEscape:
            if(*o->tokenPtr++ != '\134')
               return JLexerT_ParseErr;
            o->state=JLexerSt_StringSurrogateU;
            break;

         case JLexerSt_StringSurrogateU:
            if(*o->tokenPtr++ != '\165')
               return JLexerT_ParseErr;
            o->unicode=0;
            o->unicodeShift=12;
            o->state=JLexerSt_StringUnicode;
            break;

         case JLexerSt_StringUtf8:
         {
            U32 minUnicode;
            U8 c=*o->tokenPtr;
            if((c&0xc0) != 0x80)
               return JLexerT_ParseErr;
            if(JDBuf_expandIfNeeded(o->asmB,1))
               return JLexerT_MemErr;
            asmB->buf[asmB->index++]=c;
            o->tokenPtr++;
            o->unicode=(o->unicode<<6)|(c&0x3f);
            if(--o->unicodeShift)
               break;
            minUnicode=o->utf8Len == 2 ? 0x80 :
               (o->utf8Len == 3 ? 0x800 : 0x10000);
            if(o->unicode < minUnicode || o->unicode > 0x10ffff ||
               (o->unicode >= 0xd800 && o->unicode <= 0xdfff))
               return JLexerT_ParseErr;
            o->state=JLexerSt_String;
            break;
         }

         case JLexerSt_Number:
            while(strchr(jsonNumberChars, *o->tokenPtr))
            {
               if(JDBuf_expandIfNeeded(o->asmB, 2))
                  return JLexerT_MemErr;
               if(*o->tokenPtr=='\056' || *o->tokenPtr=='\145' || *o->tokenPtr=='\105')
                  o->isDouble=TRUE;
               asmB->buf[asmB->index++] = *o->tokenPtr++;
               if(o->tokenPtr == o->bufEnd)
                  return JLexerT_NeedMoreData;
            }
            asmB->buf[asmB->index]=0;
            o->state = JLexerSt_GetNextToken;
            return JLexerT_Number;

         case JLexerSt_GetNextToken:
            switch(*o->tokenPtr)
            {
               case '\173':
                  o->tokenPtr++;
                  return JLexerT_BeginObject;

               case '\175':
                  o->tokenPtr++;
                  return JLexerT_EndObject;

               case '\133':
                  o->tokenPtr++;
                  return JLexerT_BeginArray;

               case '\135':
                  o->tokenPtr++;
                  return JLexerT_EndArray;

               case '\054':
                  o->tokenPtr++;
                  return JLexerT_Comma;

               case '\072':
                  o->tokenPtr++;
                  return JLexerT_MemberSep;

               case '\164':
               case '\124':
               case '\146':
               case '\106':
                  o->state = JLexerSt_TrueFalseNull;
                  o->retVal = JLexerT_Boolean;
                  if(*o->tokenPtr == '\146' || *o->tokenPtr == '\124')
                  {
                     o->typeChkPtr = falseString;
                     o->sn = FALSE;
                  }
                  else
                  {
                     o->typeChkPtr = trueString;
                     o->sn = TRUE;
                  }
                  o->tokenPtr++;
                  break;

               case '\156':
               case '\116':
                  o->tokenPtr++;
                  o->typeChkPtr = nullString;
                  o->retVal = JLexerT_Null;
                  o->state = JLexerSt_TrueFalseNull;
                  break;

               case '\042':
               case '\047':
                  baAssert(asmB->index==0);
                  if(JDBuf_expandIfNeeded(o->asmB, 2))
                     return JLexerT_MemErr;
                  o->sn = *o->tokenPtr++;
                  o->surrogate=0;
                  o->utf8Len=0;
                  o->state = JLexerSt_String;
                  break;

               case '\040':
               case '\011':
               case '\012':
               case '\015':
                  o->tokenPtr++;
                  break;

               case '\055': 
                  o->tokenPtr++;
                  o->sn = 255;
                  o->state = JLexerSt_Number;
                  baAssert(asmB->index==0);
                  if(JDBuf_expandIfNeeded(o->asmB, 256))
                     return JLexerT_MemErr;
                  break;

               case '\057':
                  o->tokenPtr++;
                  o->state = JLexerSt_StartComment;
                  break;

               default:
                  baAssert(asmB->index==0);
                  if(isdigit(*o->tokenPtr))
                  {
                     o->sn = 0;
                     o->state = JLexerSt_Number;
                     if(JDBuf_expandIfNeeded(o->asmB, 256))
                        return JLexerT_MemErr;
                     break;
                  }
                  else
                     return JLexerT_ParseErr;
            }
      }
   }
}




static int
aintcconfig(JParser* o, JParsStat s, int retVal)
{
   o->status = (U8)s;
   if(retVal)
   {
      o->stackIx=0;
      o->state = JParserSt_StartObj;
   }
   return retVal;
}

static int
pinnedasids(JParser* o)
{
   int retVal = JParserIntf_serviceCB(o->intf, &o->val, o->stackIx);
   if(retVal)
      aintcconfig(o, JParsStat_IntfErr, -1);
   o->val.memberName[0]=0;
   o->val.memberNameLen=0;
   o->val.memberNameSet=FALSE;
   o->val.stringLen=0;
   return retVal;
}



void
JParser_constructor(JParser* o, JParserIntf* intf, char* nameBuf,
                    int namebufSize, AllocatorIntf* alloc, int extraStackLen)
{
   memset(o, 0, sizeof(JParser));
   pcsxxstatus1(&o->mnameB, 0);
   o->val.memberName = nameBuf;
   o->mnameB.buf = (U8*)nameBuf;
   nameBuf[0]=0;
   o->mnameB.size = (size_t)namebufSize;
   pcsxxstatus1(&o->asmB, alloc);
   JLexer_constructor(&o->lexer,&o->asmB);
   o->intf = intf;
   o->status = JParsStat_DoneEOS;
   o->state = JParserSt_StartObj;
   o->stackIx = 0;
   o->stackSize = (U16)(JPARSER_STACK_LEN + extraStackLen);
}


void
JParser_destructor(JParser* o)
{
   JDBuf_destructor(&o->asmB);
}


int
JParser_parse(JParser* o, const U8* buf, U32 size)
{
   JLexerT lexerT;
   if(o->status == JParsStat_DoneEOS || o->status == JParsStat_NeedMoreData)
      JLexer_setBuf(&o->lexer,buf,size);
   else if(o->status != JParsStat_Done)
   {
      baAssert(o->status == JParsStat_ParseErr ||
               o->status == JParsStat_MemErr ||
               o->status == JParsStat_IntfErr);
      return -1;
   }

   for(;;)
   {
      lexerT = processorstate(&o->lexer);
      if(lexerT == JLexerT_NeedMoreData)
         return aintcconfig(o, JParsStat_NeedMoreData, 0);
      if(lexerT == JLexerT_ParseErr)
         return aintcconfig(o, JParsStat_ParseErr, -1);
      if(lexerT == JLexerT_MemErr)
         return aintcconfig(o, JParsStat_MemErr, -1);

      switch(o->state)
      {
         case JParserSt_StartObj:
        L_startObj:
            if( (o->stackIx + 1) >= o->stackSize)
               return aintcconfig(o, JParsStat_StackOverflow, -1);
            o->stack[o->stackIx] = (U8)lexerT; 
            if(lexerT == JLexerT_BeginObject)
            {
               o->val.t = JParserT_BeginObject;
               o->lexer.asmB = &o->mnameB;
               o->state = JParserSt_MemberName;
            }
            else if(lexerT == JLexerT_BeginArray)
            {
               o->val.t = JParserT_BeginArray;
               o->state = JParserSt_BeginArray;
            }
            else
               return aintcconfig(o, JParsStat_ParseErr, -1);
            if(pinnedasids(o)) return -1;
            o->stackIx++;
            break;

         case JParserSt_BeginArray:
            if(lexerT == JLexerT_EndArray)
               goto L_endArray;
            else
               goto L_value;

         case JParserSt_MemberName:
            o->val.memberNameLen=o->mnameB.index;
            o->val.memberNameSet=lexerT == JLexerT_String;
            JDBuf_reset(&o->mnameB);
            o->lexer.asmB = &o->asmB;
            if(lexerT == JLexerT_EndObject)
               goto L_endObj;
            if(lexerT != JLexerT_String)
               return aintcconfig(o, JParsStat_ParseErr, -1);
            o->state = JParserSt_MemberSep;
            break;

         case JParserSt_MemberSep:
            if(lexerT != JLexerT_MemberSep)
               return aintcconfig(o, JParsStat_ParseErr, -1);
            o->state = JParserSt_Value;
            break;

         case JParserSt_Value:
        L_value:
            if(lexerT == JLexerT_BeginObject ||
               lexerT == JLexerT_BeginArray)
            {
               goto L_startObj;
            }
            if(omap2pwrdm(&o->lexer, lexerT, &o->val))
               return aintcconfig(o, JParsStat_ParseErr, -1);
            if(pinnedasids(o)) return -1;
            o->state = JParserSt_Comma;
            break;

         case JParserSt_Comma:
            if(o->stack[o->stackIx-1] == JLexerT_BeginObject)
            {
               if(lexerT == JLexerT_Comma)
               {
                  o->lexer.asmB = &o->mnameB;
                  o->state = JParserSt_MemberName;
               }
               else if(lexerT == JLexerT_EndObject)
               {
                 L_endObj:
                  if(o->stack[o->stackIx-1] != JLexerT_BeginObject)
                     return aintcconfig(o, JParsStat_ParseErr, -1);
                  o->val.t = JParserT_EndObject;
                  o->stackIx--;
                  if(pinnedasids(o)) return -1;
                  if(o->stackIx == 0)
                  {
L_endParse:
                     return aintcconfig(
                        o, writeguest(&o->lexer) ?
                        JParsStat_Done : JParsStat_DoneEOS, 1);
                  }
                  o->state = JParserSt_Comma;
               }
               else
                  return aintcconfig(o, JParsStat_ParseErr, -1);
            }
            else
            {
               baAssert(o->stack[o->stackIx-1] == JLexerT_BeginArray);
               if(lexerT == JLexerT_Comma)
                  o->state = JParserSt_Value;
               else if(lexerT == JLexerT_EndArray)
               {
                 L_endArray:
                  if(o->stack[o->stackIx-1] != JLexerT_BeginArray)
                     return aintcconfig(o, JParsStat_ParseErr, -1);
                  o->val.t = JParserT_EndArray;
                  o->stackIx--;
                  if(pinnedasids(o)) return -1;
                  if(o->stackIx == 0)
                     goto L_endParse;
                  o->state = JParserSt_Comma;
               }
               else
                  return aintcconfig(o, JParsStat_ParseErr, -1);
            }
            break;

         default:
            baAssert(0);
      } 
   } 
}











