      ((SHARKSSL_UNALIGNED_U32*)output)[1] = ((SHARKSSL_UNALIGNED_U32*)input)[1] ^ ((SHARKSSL_UNALIGNED_U32*)q)[1];
      ((SHARKSSL_UNALIGNED_U32*)output)[2] = ((SHARKSSL_UNALIGNED_U32*)input)[2] ^ ((SHARKSSL_UNALIGNED_U32*)q)[2];
      ((SHARKSSL_UNALIGNED_U32*)output)[3] = ((SHARKSSL_UNALIGNED_U32*)input)[3] ^ ((SHARKSSL_UNALIGNED_U32*)q)[3];
      #else
      output[0]  = (U8)(input[0]  ^ q[0]);
      output[1]  = (U8)(input[1]  ^ q[1]);
      output[2]  = (U8)(input[2]  ^ q[2]);
      output[3]  = (U8)(input[3]  ^ q[3]);
      output[4]  = (U8)(input[4]  ^ q[4]);
      output[5]  = (U8)(input[5]  ^ q[5]);
      output[6]  = (U8)(input[6]  ^ q[6]);
      output[7]  = (U8)(input[7]  ^ q[7]);
      output[8]  = (U8)(input[8]  ^ q[8]);
      output[9]  = (U8)(input[9]  ^ q[9]);
      output[10] = (U8)(input[10] ^ q[10]);
      output[11] = (U8)(input[11] ^ q[11]);
      output[12] = (U8)(input[12] ^ q[12]);
      output[13] = (U8)(input[13] ^ q[13]);
      output[14] = (U8)(input[14] ^ q[14]);
      output[15] = (U8)(input[15] ^ q[15]);
      #endif
      SharkSslAesCtx_encrypt(ctx, output, output);
      q  = output;
