      ((SHARKSSL_UNALIGNED_U32*)output)[2] ^= ((SHARKSSL_UNALIGNED_U32*)q)[2];
      ((SHARKSSL_UNALIGNED_U32*)output)[3] ^= ((SHARKSSL_UNALIGNED_U32*)q)[3];
      #else
