      output[1]  ^= q[1];
      output[2]  ^= q[2];
      output[3]  ^= q[3];
      output[4]  ^= q[4];
      output[5]  ^= q[5];
      output[6]  ^= q[6];
      output[7]  ^= q[7];
      output[8]  ^= q[8];
      output[9]  ^= q[9];
      output[10] ^= q[10];
      output[11] ^= q[11];
      output[12] ^= q[12];
      output[13] ^= q[13];
      output[14] ^= q[14];
      output[15] ^= q[15];
