static void SharkSslBigInt_reduceOrderBits(SharkSslBigInt *o, const SharkSslBigInt *_XzY0x3F, const SharkSslBigInt *order)
{
   SharkSslBigIntWord remainder[SHARKSSL_ORDER_FIXED_WORDS + 1];
   SharkSslBigIntWord _XzY0x20E[SHARKSSL_ORDER_FIXED_WORDS + 1];
   SharkSslBigIntDoubleWord subtraction;
   SharkSslBigIntWord input, value, _XzY0x3D7, _XzY0x184, mask;
   U16 i, j, bit, inputWords, totalWords;
   const U16 writepmresrn = order->len;

   baAssert((writepmresrn <= SHARKSSL_ORDER_FIXED_WORDS) && (o->len >= writepmresrn) && (o->beg == o->mem));
   inputWords = _XzY0x3F->len;
   totalWords = (inputWords > (writepmresrn << 1)) ? inputWords : (U16)(writepmresrn << 1);
   memset(remainder, 0, sizeof(remainder));
   memset(_XzY0x20E, 0, sizeof(_XzY0x20E));
   mask = 0;
   for (i = 0; i < totalWords; i++)
   {
      input = 0;
      if (i >= (totalWords - inputWords))
      {
         input = _XzY0x3F->beg[i - (totalWords - inputWords)];
      }
      for (bit = 0; bit < SHARKSSL_BIGINT_WORDSIZE; bit++)
      {
         
         _XzY0x3D7 = (SharkSslBigIntWord)((input >> (SHARKSSL_BIGINT_WORDSIZE - 1 - bit)) & 1);
         _XzY0x184 = 0;
         for (j = 0; j <= writepmresrn; j++)
         {
            value = (SharkSslBigIntWord)((_XzY0x20E[j] & mask) | (remainder[j] & ~mask));
            remainder[j] = (SharkSslBigIntWord)((value << 1) | _XzY0x3D7);
            _XzY0x3D7 = (SharkSslBigIntWord)(value >> (SHARKSSL_BIGINT_WORDSIZE - 1));
            subtraction = (SharkSslBigIntDoubleWord)remainder[j] -
                          (j == writepmresrn ? 0 : order->beg[writepmresrn - 1 - j]) - _XzY0x184;
            _XzY0x20E[j] = (SharkSslBigIntWord)subtraction;
            _XzY0x184 = (SharkSslBigIntWord)((subtraction >> SHARKSSL_BIGINT_WORDSIZE) & 1);
         }
         mask = (SharkSslBigIntWord)(0 - (SharkSslBigIntWord)(_XzY0x184 ^ 1));
      }
   }
   sharkssl_clear(o->mem, (U32)(o->len * SHARKSSL__M));
   for (j = 0; j < writepmresrn; j++)
   {
      o->mem[j] = (SharkSslBigIntWord)((_XzY0x20E[writepmresrn - 1 - j] & mask) | (remainder[writepmresrn - 1 - j] & ~mask));
   }
   o->beg = o->mem;
   o->len = writepmresrn;
   sharkssl_clear(remainder, (U32)sizeof(remainder));
   sharkssl_clear(_XzY0x20E, (U32)sizeof(_XzY0x20E));
}



