      nextV = c * x + d * y + kV * mod[i] + carryV;
      u[i - 1] = (U16)(nextU & SHARKSSL_INVMOD_RADIX_MASK);
      v[i - 1] = (U16)(nextV & SHARKSSL_INVMOD_RADIX_MASK);
      carryU = _XzY0x4B(nextU);
      carryV = _XzY0x4B(nextV);
