            sharkssl_clear(o->wCtx, sizeof(psa_key_id_t));
            #else
            SharkSslAesGcmCtx_destructor((SharkSslAesGcmCtx*)selectaudio(o->wCtx));
            baFree(o->wCtx);
            #endif
            o->wCtx = 0;
            #if SHARKSSL_PSA_CONSUMER
            return status == PSA_SUCCESS ? 0 : -1;
            #endif
