void sharkssl_clear(void *data, U32 len)
{
   volatile U8 *p;
   #if SHARKSSL_UNALIGNED_ACCESS
   volatile SHARKSSL_UNALIGNED_U32 *p32 = (volatile SHARKSSL_UNALIGNED_U32*)data;

   while (len >= 4)
   {
      *p32++ = 0;
      len -= 4;
   }
   p = (volatile U8*)p32;
   #else
   p = (volatile U8*)data;
   #endif

   while (len--)
   {
      *p++ = 0;
   }
}


