static void
edma1device(BufPrint* b, const char* userPass, BaBool domainremove)
{
   if(domainremove)
      BufPrint_write(b,"\120\162\157\170\171\055", 6);
   BufPrint_write(b,"\101\165\164\150\157\162\151\172\141\164\151\157\156\072\040\102\141\163\151\143\040",21);
   BufPrint_b64Encode(b, userPass, iStrlen(userPass));
   BufPrint_write(b,"\015\012",2);
}


static char*
mkHostName(const char* ptr, int len, BaBool *hotplugshutdown)
{
   char* host;
   
   if(ptr[0] == '\133' && len > 2 && ptr[len-1] == '\135')
   {
      ptr++;
      len-=2;
      *hotplugshutdown = TRUE;
   }

   host = baMalloc(len+1);
   if(host)
   {
      strncpy(host, ptr, len);
      host[len]=0;
   }
   return host;
}



int
HttpClient_isURL(const char* url)
{
   int status;
   if(url[0] == '\150' && url[1] == '\164' && url[2] == '\164' && url[3] == '\160')
   {
      if(url[4] == '\163')
      {
         status=2;
         url++;
      }
      else
         status=1;
      if(url[4] == '\072' && url[5] == '\057' && url[6] == '\057')
         return status;
   }
   else if(url[0] == '\167' && url[1] == '\163')
   {
      if(url[2] == '\163')
      {
         status=4;
         url++;
      }
      else
         status=3;
      if(url[2] == '\072' && url[3] == '\057' && url[4] == '\057')
         return status;
   }
   return E_INVALID_URL;
}


static int
mastermemory1(HttpClient* o, U8* buf, int len)
{
   int ix=0;
   while(ix != len)
   {
      int resp;
      SoDispCon_setReadTmo((SoDispCon*)o,o->readTmo);
      resp=SoDispCon_blockRead((SoDispCon*)o, buf+ix, len-ix);
      if(resp < 0)
         return resp;
      ix += resp;
   }
   return 0;
}


static int
updateproperty(HttpClient* o, int error)
{
   if(!o->lastError)
      o->lastError=error;
   return o->lastError;
}



static void
supportentry(HttpClient* o)
{
   if(! SoDispCon_recEvActive((SoDispCon*)o))
   {
      if( ! SoDispCon_dispatcherHasCon((SoDispCon*)o) )
      {
         SoDisp_addConnection(SoDispCon_getDispatcher(
                                 (SoDispCon*)o),(SoDispCon*)o);
      }
      SoDisp_activateRec(SoDispCon_getDispatcher((SoDispCon*)o),(SoDispCon*)o);
   }
}



static int
pcie0controller(HttpClient* o)
{
   char* ptr;
   BufPrint* b = (BufPrint*)&o->db;
   o->data=0;
   for(ptr = b->buf ; ptr+1 < b->buf+b->cursor; ptr++)
   {
      if(*ptr == '\015' && ptr+3 < b->buf+b->cursor &&
         ptr[1] == '\012' && ptr[2] == '\015' && ptr[3] == '\012')
      {
         o->data = ptr+4;
         *ptr=0;
         return TRUE;
      }
      if(*ptr == '\012' && ptr[1] == '\012')
      {
         o->data = ptr+2;
         *ptr=0;
         return TRUE;
      }
   }
   return FALSE;
}



static int
fixmapoffset(HttpClient* o)
{
   int len;
   DynBuffer* db = &o->db;
   BufPrint* b = (BufPrint*)db;
   while( ! pcie0controller(o) )
   {
      if(b->cursor > 8192) 
         return updateproperty(o,E_INVALID_RESPONSE);
      if(DynBuffer_expand(db, 1024))
         return updateproperty(o,E_MALLOC);
      SoDispCon_setReadTmo((SoDispCon*)o,o->readTmo);
      if( (len=SoDispCon_blockRead(
              (SoDispCon*)o,b->buf+b->cursor,1024)) <= 0)
      {
         return updateproperty(o,len);
      }
      DynBuffer_incrementCursor(db, len);
   };
   return 0;
}


static int
exceptionenter(HttpClient* o)
{
   BufPrint* b = (BufPrint*)&o->db;
   char* deltaserio; 
   char* end; 
   char* ptr;
   
   BaBool ecoffesecs;

   
   ptr = deltaserio = b->buf; 
   if(o->data-deltaserio < 15 || memcmp(ptr,"\110\124\124\120\057\061\056",7) ||
      ptr[7]<'\060' || ptr[7]>'\071' || ptr[8]!='\040' ||
      ptr[9]<'\061' || ptr[9]>'\065' || ptr[10]<'\060' || ptr[10]>'\071' ||
      ptr[11]<'\060' || ptr[11]>'\071' || ptr[12]!='\040')
      return updateproperty(o,E_INVALID_RESPONSE);
   o->httpStatus=(S16)((ptr[9]-'\060')*100+(ptr[10]-'\060')*10+ptr[11]-'\060');
   end=ptr+12;
   o->headerLen=0;
   
   ptr = strchr(end, '\012');
   if((ptr) && (*ptr)) 
   {
      ptr++; 

      
      o->headerLen=0;
      ecoffesecs=TRUE;
      o->headers[0].key = (U16)(ptr - deltaserio); 
      for( ; *ptr ; ptr++)
      {
         switch(*ptr)
         {
            case '\015':
            case '\012':
               if(ecoffesecs)
                  return updateproperty(o,E_INVALID_RESPONSE);
               if( (ptr[0] == '\015' && ptr[1] == '\012') ||  
                   ptr[0] == '\012')                        
               {
                  if( (ptr[0] == '\015' && (ptr[2] == '\040' || ptr[2] == '\011')) ||
                      (ptr[0] == '\012' && (ptr[1] == '\040' || ptr[1] == '\011'))   )
                  {
                     ptr++; 
                  }
                  else
                  { 
                     *ptr=0; 
                     ptr = ptr[1] == '\012' ? ptr+2 : ptr+1; 
                     if(++o->headerLen == HTTP_CLIENT_MAX_HEADERS)
                        return updateproperty(o,E_INVALID_RESPONSE);
                     o->headers[o->headerLen].key = (U16)(ptr - deltaserio);
                     ecoffesecs=TRUE;
                  }
               }
               break;
            case '\072':
               if(ecoffesecs)
               {
                  *ptr++=0;
                  httpEatWhiteSpace(ptr);
                  o->headers[o->headerLen].val = (U16)(ptr - deltaserio);
                  ecoffesecs=FALSE;
               }
               break;
         }
      }
      if(ecoffesecs)
         return updateproperty(o,E_INVALID_RESPONSE);
      o->headerLen++;
   }

   if(o->httpStatus < 200 && o->httpStatus != 101)
   {
      char* end = b->buf+b->cursor;
      baAssert(o->data);
      if(o->data < end)
      {
         b->cursor = (int)(end - o->data);
         memmove(b->buf, o->data, b->cursor);
      }
      else
         b->cursor=0;
      o->headerLen=0;
      o->data=0;
      o->httpStatus=0; 
   }

   return 0;
}



static void
signalpending(SoDispCon* super)
{
   HttpClient* o = (HttpClient*)super;
   DynBuffer* db = &o->db;
   BufPrint* b = (BufPrint*)db;

   if(o->respManaged) 
   {
      SoDispCon_closeCon(super);
      return;
   }
   if(b->cursor <= 8192) 
   {
      if(!DynBuffer_expand(db, 1024))
      {
         int len = SoDispCon_readData(super, b->buf+b->cursor, 1024, FALSE);
         if(len)
         {
            if(len > 0)
            {
               DynBuffer_incrementCursor(db, len);
               while(!o->httpStatus && pcie0controller(o))
               {
                  if(exceptionenter(o)) break;
               }
               if(o->httpStatus)
               {
                  SoDisp_deactivateRec(super->dispatcher,super);
                  if(o->httpStatus < 200 || o->httpStatus >= 300)
                     updateproperty(o,E_SOCKET_WRITE_FAILED);
               }
            }
            else
               updateproperty(o,len);
         }
      }
      else
         updateproperty(o,E_MALLOC);
   }
   else
      updateproperty(o,E_INVALID_RESPONSE);
   if(o->lastError)
      SoDispCon_closeCon((SoDispCon*)o);
}



static int
powerdomain(HttpClient* o)
{
   int n;
   HttpClientHeader* h;
   BaBool systabreport = HttpClient_usePersistent(o);
   BaBool _XzY0x163=FALSE;

   if(o->lastError)
      return o->lastError;

   if(o->respManaged)
      return 0;

   if(o->size != 0) 
      return  updateproperty(o,E_INCORRECT_USE);

   
   if(o->chunkEncoding)
   {
      if(SoDispCon_sendData((SoDispCon*)o,"\060\015\012\015\012", 5))
         return updateproperty(o,E_SOCKET_WRITE_FAILED);
      o->chunkEncoding=FALSE;
   }

   
   if(SoDispCon_recEvActive((SoDispCon*)o))
   {
      SoDisp_deactivateRec(SoDispCon_getDispatcher((SoDispCon*)o),
                          (SoDispCon*)o);
   }
   if( !o->httpStatus )
   {
      do
      {
         if( (n = fixmapoffset(o)) ||
             (n = exceptionenter(o)) )
         {
            return n;
         }
      } while(!o->httpStatus);
   }

   n = o->headerLen;
   h = o->headers;
   for( ; n > 0 ; h++,n--)
   {
      const char* k = HttpClientHeader_key(o,h);
      switch(*k)
      {
         case '\124':
         case '\164':
            if( ! baStrCaseCmp(k, "\124\162\141\156\163\146\145\162\055\105\156\143\157\144\151\156\147") )
            {
               const char* value=HttpClientHeader_val(o,h);
               if(o->chunkEncoding || baStrnCaseCmp(value,"\143\150\165\156\153\145\144",7))
                  return updateproperty(o,E_INVALID_RESPONSE);
               value+=7;
               httpEatWhiteSpace(value);
               if(*value) return updateproperty(o,E_INVALID_RESPONSE);
               o->chunkEncoding=TRUE;
               o->chunkSize=0;
            }
            break;
         case '\103':
         case '\143':
            if( ! baStrCaseCmp(k, "\103\157\156\164\145\156\164\055\114\145\156\147\164\150") )
            {
               const char* value=HttpClientHeader_val(o,h);
               const BaFileSize max=((BaFileSize)-1)>>1;
               for(;;)
               {
                  BaFileSize length=0;
                  httpEatWhiteSpace(value);
                  if(*value<'\060' || *value>'\071')
                     return updateproperty(o,E_INVALID_RESPONSE);
                  do
                  {
                     unsigned bootmemalloc=(unsigned)(*value++-'\060');
                     if(length>(max-bootmemalloc)/10)
                        return updateproperty(o,E_INVALID_RESPONSE);
                     length=length*10+bootmemalloc;
                  } while(*value>='\060' && *value<='\071');
                  if(_XzY0x163 && o->size!=length)
                     return updateproperty(o,E_INVALID_RESPONSE);
                  o->size=length;
                  _XzY0x163=TRUE;
                  httpEatWhiteSpace(value);
                  if(!*value) break;
                  if(*value++!='\054')
                     return updateproperty(o,E_INVALID_RESPONSE);
               }
            }
            else if( systabreport && ! baStrCaseCmp(k, "\103\157\156\156\145\143\164\151\157\156") )
            {
               if(! baStrCaseCmp(HttpClientHeader_val(o,h), "\103\154\157\163\145") )
                  systabreport=FALSE;
            }
            break;
      }
   }
   if(o->chunkEncoding)
   {
      if(_XzY0x163) return updateproperty(o,E_INVALID_RESPONSE);
      o->size=1; 
   }
   if(o->methodType == HttpMethod_Head || o->httpStatus == 101 ||
      o->httpStatus == 204 || o->httpStatus == 304)
   {
      o->size=0;
      _XzY0x163=TRUE;
      if(o->httpStatus == 101) systabreport=FALSE;
   }
   if(!o->size)
   {
      if(systabreport)
         supportentry(o);
      else if(!_XzY0x163)
         o->size = ~((BaFileSize)0); 
   }
   else if(systabreport && o->methodType == HttpMethod_Head)
      supportentry(o);
   if( ! systabreport )
      o->closeCon=TRUE;
   o->respManaged=TRUE;
   return 0;
}



static int
xilinxtimer(HttpClient* o, U8* buf)
{
   HttpSockaddr addr;
   U8* arm64panic = buf;
   int resp;
   *arm64panic++=5; 
   *arm64panic++=1; 
   *arm64panic++=0;  
   
   HttpSockaddr_inetAddr(&addr, o->host, HttpClient_useIPv6(o), &resp);
   if(resp == 0)
   {
      if(HttpClient_useIPv6(o))
      {
         *arm64panic++=4; 
         memcpy(arm64panic, addr.addr, 16);
         arm64panic+=16;
      }
      else
      {
         *arm64panic++=1; 
         memcpy(arm64panic, addr.addr, 4);
         arm64panic+=4;
      }
   }
   else 
   {
      int dn = iStrlen(o->host);
      *arm64panic++=3; 
      *arm64panic++ = (U8)dn;
      memcpy(arm64panic, o->host, dn);
      arm64panic+=dn;

   }
   *arm64panic++ = (U8)(o->portNo >> 8);
   *arm64panic++ = (U8)(o->portNo);

   if( ! (resp = SoDispCon_sendData(
             (SoDispCon*)o,buf,(int)(arm64panic-buf))) &&
       ! (resp = mastermemory1(o, buf, 4)) )
   {
      if(buf[1])
      {
         switch(buf[1])
         {
            case 1: 
               resp=E_PROXY_GENERAL; break;
            case 2: 
               resp= E_PROXY_NOT_ALLOWED; break;
            case 3: 
               resp=E_PROXY_NETWORK; break;
            case 4: 
               resp=E_PROXY_HOST; break;
            case 5: 
               resp=E_PROXY_REFUSED; break;
            case 6: 
               resp=E_PROXY_TTL; break;
            case 7: 
               resp= E_PROXY_COMMAND_NOT_SUP; break;
            case 8: 
               resp=E_PROXY_ADDRESS_NOT_SUP; break;
            default:
               resp=E_PROXY_UNKNOWN; break;
         }
         resp = updateproperty(o, resp);
      }
      else
      {
         int size=0;
         if(buf[3] == 1) size = 4;
         else if(buf[3] == 4) size = 16;
         else if(buf[3] == 3) size = buf[4]+1;
         if(size)
            resp=mastermemory1(o, buf, size+2); 
         else
            resp=updateproperty(o,E_PROXY_UNKNOWN);
      }
   }
   return resp;
}




static int
memoryregion(HttpClient* o, U8* buf)
{
   char* am35xclkdm = strchr(o->proxyUserPass, '\072');
   U8* arm64panic = buf;
   int size=3;
   int len;
   *arm64panic++=1; 
   if(am35xclkdm)
   {
      
      len = (int)(am35xclkdm - o->proxyUserPass);
      if(len <= 255)
      {
         size+=len;
         *arm64panic++=(U8)len; 
         memcpy(arm64panic, o->proxyUserPass, len);
         arm64panic+=len;
         am35xclkdm++;
         len = iStrlen(am35xclkdm);
         if(len <= 255)
         {
            int resp;
            size+=len;
            *arm64panic++=(U8)len; 
            memcpy(arm64panic, am35xclkdm, len);
            if( ! (resp = SoDispCon_sendData(
                      (SoDispCon*)o,buf,size)) &&
                ! (resp = mastermemory1(o, buf, 2)) )
            {
               
               if(buf[1]) 
                  resp=updateproperty(o,E_PROXY_AUTH);
               else
                  resp=xilinxtimer(o, buf);
            }
            return resp;
         }
      }
   }
   return E_INCORRECT_USE;
}


static int
majorversion(HttpClient* o)
{
   int resp;
   resp=SoDispCon_connect((SoDispCon*)o,o->proxy,
                          o->proxyPortNo,o->intfName, 0 ,800, FALSE,
                          HttpClient_useIPv6(o), 0);
   if(resp)
      return resp;
   SoDispCon_setTCPNoDelay((SoDispCon*)o, TRUE);
   if(HttpClient_useSocksProxy(o))
   {
      U8* buf;
      int len = iStrlen(o->host);
      
      resp = o->proxyUserPass ? iStrlen(o->proxyUserPass) : 0;
      if(len < resp)
         len=resp;
      
      buf = (U8*)baMalloc(len+30);
      if(buf)
      {
         buf[0] = 5;  
         buf[1]= 2; 
         buf[2] = 0; 
         buf[3] = 2; 
         if( ! (resp = SoDispCon_sendData((SoDispCon*)o,buf,4)) )
         {
            if( ! (resp = mastermemory1(o, buf, 2)) )
            {
               if(buf[0] != 5)
                  resp = updateproperty(o, E_PROXY_NOT_COMPATIBLE);
               else if(buf[1] == 2)
               {
                  if(o->proxyUserPass)
                     resp=memoryregion(o, buf);
                  else
                     resp=updateproperty(o,E_PROXY_AUTH);
               }
               else if(buf[1] == 0)
                  resp=xilinxtimer(o, buf);
               else
                  resp=updateproperty(o,E_PROXY_UNKNOWN);
            }
         }
         baFree(buf);
         if(resp > 0) 
         {
            DynBuffer_getBuf(&o->db); 
            exceptionenter(o); 
         }
      }
   }
   else
   {   
      BufPrint* b = (BufPrint*)&o->db; 
      BufPrint_erase(b);
      BufPrint_printf(b, "\103\117\116\116\105\103\124\040\045\163\072\045\165\040\110\124\124\120\057\061\056\060\015\012"
                      "\125\163\145\162\055\101\147\145\156\164\072\040\102\141\162\162\141\143\165\144\141\040\123\145\162\166\145\162\015\012",
                      o->host, o->portNo);
      if(o->proxyUserPass)
         edma1device(b, o->proxyUserPass, TRUE);
      BufPrint_write(b, "\015\012", 2);
      if(BufPrint_getBuf(b))
      {
         if( ! (resp = SoDispCon_sendData(
                   (SoDispCon*)o,
                   BufPrint_getBuf(b),
                   BufPrint_getBufSize(b))) )
         {
            BufPrint_erase(b);
            do
            {
               resp=fixmapoffset(o);
               if(!resp) resp=exceptionenter(o);
            } while(!resp && !o->httpStatus);
            if(!resp)
            {
               if(o->httpStatus == 200)
               {
                  o->httpStatus=0;
                  o->headerLen=0; 
               }
               else
               {
                  resp = o->httpStatus;
               }
            }
         }
      }
      else
         resp=E_MALLOC;
   }
   o->data=0; 
   if(resp)
      return updateproperty(o, resp);
   return 0;
}



static char*
HttpClient_escapePath(char* out, const char* path)
{
   char* from=out;
   char* to=out;
   httpEscape(out,path);
   while(*from)
   {
      int devicegpiokeys=from[0]=='\045' && from[1]=='\062' && from[2]=='\065' &&
         isxdigit((unsigned char)from[3]) && isxdigit((unsigned char)from[4]);
      *to++=*from;
      from+=devicegpiokeys ? 3 : 1;
   }
   *to=0;
   return to;
}


int
HttpClient_request(HttpClient* o,
                   HttpMethod methodType,
                   const char* url,
                   const char* userPass,
                   const HttpClientKeyVal* params,
                   const HttpClientKeyVal* headers,
                   BaFileSize size)
{
   const char* port;
   const char* path;
   const char* method;
   char* ptr;
   BufPrint* b = (BufPrint*)&o->db;
   int resp;
   int hostLen;
   int portNo;
   BaBool clkctrlprovider = FALSE;
   BaBool hotplugshutdown;
   BaBool pcibiosconfig;

   if(o->lastError)
      SoDispCon_closeCon((SoDispCon*)o);
   else if( ! o->respManaged ) 
   {
      o->lastError=E_INCORRECT_USE;
      return E_INCORRECT_USE;
   }
   if (o->readTmo == 0)
      o->readTmo = 100; 
   o->lastError=E_INCORRECT_USE;
   o->httpStatus=E_SOCKET_CLOSED;

   hotplugshutdown = HttpClient_useIPv6(o);
   if( (resp = HttpClient_isURL(url)) < 0 )
      return E_INVALID_URL;
   if(resp == 2 || resp == 4)
   {
      if(!o->sharkSslClient)
         return E_TLS_NOT_ENABLED;
      pcibiosconfig = TRUE;
   }
   else
      pcibiosconfig = FALSE;
   switch(resp)
   {
      case 1: url+= 7; break;
      case 2: url+= 8; break;
      case 3: url+= 5; break;
      case 4: url+= 6; break;
      default: baAssert(0);
   }
   path=strchr(url, '\057');
   if(!path)
      path=url+strlen(url); 

   if(path > url && isdigit(*(path-1)))
   {
      for(port = path-2 ; ; port--)
      {
         if(path > url)
         {
            if( ! isdigit(*port) )
            {
               if(*port != '\072')
                  goto L_defPorts;
               portNo=U32_atoi2(port+1,path);
               break;
            }
         }
         else
            return E_INVALID_URL;
      }
   }
   else
   {
L_defPorts:
      portNo=pcibiosconfig ? 443 : 80;
      port=path; 
   }

   hostLen = (int)(port-url);
   o->headerLen=0;
   o->data=0;
   o->lastError=0;
   o->httpStatus=0;
   o->respManaged=FALSE;

   if(o->closeCon)
   {
      SoDispCon_closeCon((SoDispCon*)o);
      o->closeCon=FALSE;
   }

   if( ! o->host )
   {
      o->host = mkHostName(url, hostLen, &hotplugshutdown);
      o->portNo=portNo;
   }
   else if(o->portNo != portNo || baStrnCaseCmp(o->host, url, hostLen))
   {
      baFree(o->host);
      o->host = mkHostName(url, hostLen, &hotplugshutdown);
      if(SoDispCon_isValid((SoDispCon*)o))
         SoDispCon_closeCon((SoDispCon*)o);
      o->portNo = portNo;
   }
   if( ! o->host )
   {
      o->lastError=E_MALLOC;
      return E_MALLOC;
   }

   switch(methodType)
   {
      case HttpMethod_Delete: method="\104\105\114\105\124\105"; break;
      case HttpMethod_Get: method="\107\105\124"; break;
      case HttpMethod_Head: method="\110\105\101\104"; break;
      case HttpMethod_Patch: method="\120\101\124\103\110"; break;
      case HttpMethod_Post: method="\120\117\123\124"; break;
      case HttpMethod_Put: method="\120\125\124"; break;
      default:
         o->lastError=E_INVALID_PARAM;
         return E_INVALID_PARAM; 
   }

   if(SoDispCon_isValid((SoDispCon*)o))
   {
      if(SoDispCon_isValid((SoDispCon*)o) && 0 == o->size)
      {
         if(SoDispCon_recEvActive((SoDispCon*)o))
         {
            SoDisp_deactivateRec(
               SoDispCon_getDispatcher((SoDispCon*)o),(SoDispCon*)o);
         }
      }
      else
      {
         SoDispCon_closeCon((SoDispCon*)o);
         goto L_con;
      }
      clkctrlprovider=TRUE;
   }
   else
   {
     L_con:
      if(o->proxy)
      {
         resp = majorversion(o);
         if( !resp && HttpClient_proxyConnect(o) )
         {
            o->httpStatus = 204;
            return E_PROXY_READY;
         }
      }
      else
      {
         resp=SoDispCon_connect((SoDispCon*)o,o->host,(U16)o->portNo,
                                o->intfName, 0, 1500, FALSE, hotplugshutdown, 0);
      }
      if(resp)
         return updateproperty(o,resp);
      SoDispCon_setTCPNoDelay((SoDispCon*)o, TRUE);
      if(pcibiosconfig)
      {
#if !BA_ENABLE_SHARKSSL
         return updateproperty(o, E_NOT_TRUSTED);
#else
         SoDispCon_setReadTmo((SoDispCon*)o, o->readTmo);
         if( (resp=SoDispCon_upgrade((SoDispCon*)o,
                                     o->sharkSslClient, 0,
                                     o->host,o->portNo)) <= 0)
         {
            return updateproperty(o, resp);
         }
         if(o->acceptTrusted && SharkSslConTrust_CertCnDate!=
            HttpClient_trusted(o))
         {
            return updateproperty(o, E_NOT_TRUSTED);
         }
#endif
      }
      else if(o->acceptTrusted) 
         return updateproperty(o, E_NOT_TRUSTED);
   }

   o->size=0;
   BufPrint_erase(b);
   BufPrint_printf(b, "\045\163\040", method);
   
   if(*path)
   {
      if(DynBuffer_expand(&o->db, iStrlen(path)*3))
         return updateproperty(o, E_MALLOC);
      ptr=DynBuffer_getCurPtr(&o->db);
      resp = (int)(HttpClient_escapePath(ptr,path) - ptr); 
      DynBuffer_incrementCursor(&o->db, resp);
   }
   else
      BufPrint_putc(b, '\057');
   if(params)
   {
      const HttpClientKeyVal* iter;
      BufPrint_putc(b, '\077');
      for(iter=params; iter->key ; iter++)
      {
         if(iter != params)
            BufPrint_putc(b, '\046');
         if(DynBuffer_expand(&o->db, iStrlen(iter->key)*3))
            return updateproperty(o, E_MALLOC);
         ptr=DynBuffer_getCurPtr(&o->db);
         resp = (int)(httpEscape(ptr,iter->key) - ptr);
         DynBuffer_incrementCursor(&o->db, resp);
         BufPrint_putc(b, '\075');
         if(DynBuffer_expand(&o->db, iStrlen(iter->val)*3))
            return updateproperty(o, E_MALLOC);
         ptr=DynBuffer_getCurPtr(&o->db);
         resp = (int)(httpEscape(ptr,iter->val) - ptr);
         DynBuffer_incrementCursor(&o->db, resp);
      }
   }
   BufPrint_printf(b,"\040\110\124\124\120\057\061\056\045\143\015\012",HttpClient_usePersistent(o) ? '\061' : '\060');
   if( ! (o->mode & HttpClient_NoHostHeader) )
   {
      
      BufPrint_printf(b, strchr(o->host, '\072') ? "\110\157\163\164\072\040\133\045\163\135" : "\110\157\163\164\072\040\045\163", o->host);
      if(portNo != 80 && portNo != 443)
         BufPrint_printf(b, "\072\045\165", portNo);
      BufPrint_write(b, "\015\012", 2);
   }
   o->chunkEncoding=FALSE;
   if(methodType == HttpMethod_Post || 
      methodType == HttpMethod_Put ||
      methodType == HttpMethod_Delete ||
      methodType == HttpMethod_Patch)
   {
      if(size)
      {
         o->size=size;
         BufPrint_printf(b, "\103\157\156\164\145\156\164\055\114\145\156\147\164\150\072\040\045" BA_UFSF "\015\012",size);
      }
      else
      {
         o->chunkEncoding=TRUE;
         BufPrint_write(b, "\124\162\141\156\163\146\145\162\055\105\156\143\157\144\151\156\147\072\040\143\150\165\156\153\145\144\015\012",-1);
      }
   }
   if(headers)
   {
      for(; headers->key ; headers++)
      {
         BufPrint_printf(b, "\045\163\072\040\045\163\015\012",headers->key,headers->val);
      }
   }
   if(userPass)
      edma1device(b, userPass, FALSE);
   BufPrint_write(b,"\015\012",2);
   if( ! BufPrint_getBuf(b) )
      return updateproperty(o, E_MALLOC);
   o->methodType=(U8)methodType;
   resp = SoDispCon_sendData(
      (SoDispCon*)o,BufPrint_getBuf(b),BufPrint_getBufSize(b));
   BufPrint_erase(b);
   if(resp < 0 && clkctrlprovider)
   {
      clkctrlprovider=FALSE;
      SoDispCon_closeCon((SoDispCon*)o);
      goto L_con; 
   }
   if(resp < 0)
      return updateproperty(o,E_SOCKET_WRITE_FAILED);
   return 0;
}



int
HttpClient_getBufSize(HttpClient* o)
{
   char* ptr = DynBuffer_getBuf(&o->db);
   if(!o->data)
      return 0;
   baAssert(o->data > ptr);
   baAssert((int)(DynBuffer_getBufSize(&o->db)) >= (o->data - ptr));
   return DynBuffer_getBufSize(&o->db) - (int)(o->data - ptr);
}


int
HttpClient_readDataBuffered(HttpClient* o, void* buf, int bufSize)
{
   int size;
   if(o->data)
   {
      char* ptr = DynBuffer_getBuf(&o->db);
      baAssert(o->data > ptr);
      baAssert((int)(DynBuffer_getBufSize(&o->db)) >= (o->data - ptr));
      size = DynBuffer_getBufSize(&o->db) - (int)(o->data - ptr);
      if(size) 
      {
         if(size > bufSize)
         {
            if( ! o->chunkEncoding )
            {
               if((BaFileSize)bufSize > o->size)
                  return updateproperty(o, E_INVALID_RESPONSE);
               o->size -= bufSize;
            }
            memcpy(buf, o->data, bufSize);
            o->data += bufSize;
            return bufSize;
         }
         memcpy(buf, o->data, size);
         o->data = 0;
         buf = (U8*)buf+size;
         bufSize -= size;
         if( ! o->chunkEncoding )
         {
            if((BaFileSize)size > o->size)
               return updateproperty(o, E_INVALID_RESPONSE);
            o->size -= size;
         }
      }
   }
   else
      size=0;
   if(bufSize)
   {
      int decodetable;
      SoDispCon_setReadTmo((SoDispCon*)o,o->readTmo);
      decodetable = SoDispCon_blockRead((SoDispCon*)o,buf,bufSize);
      if(decodetable < 0)
      {
         
         if(!o->closeCon || o->chunkEncoding ||
            (o->size && HttpClient_getHeaderValue(o,"\103\157\156\164\145\156\164\055\114\145\156\147\164\150")))
         {
            decodetable=updateproperty(o, E_INVALID_RESPONSE);
            
            return size && !o->chunkEncoding ? size : decodetable;
         }
         decodetable=0;
      }
      else if( ! o->chunkEncoding )
      {
         if((BaFileSize)decodetable > o->size)
            return updateproperty(o, E_INVALID_RESPONSE);
         o->size -= decodetable;
      }
      return size + decodetable;
   }
   return size;
}



static int
validether(HttpClient* o)
{
   U8 line[256], c;
   int n;
   for(n=0; n<(int)sizeof(line); n++)
   {
      if(HttpClient_readDataBuffered(o,&c,1)!=1) break;
      if(c=='\015')
      {
         SBaFileSize size;
         if(HttpClient_readDataBuffered(o,&c,1)!=1 || c!='\012') break;
         size=httpParseChunkSize(line,line+n);
         if(size<0 || size>0x7FFFFFFF) break;
         return (int)size;
      }
      line[n]=c;
   }
   return updateproperty(o,E_INVALID_RESPONSE);
}



static int
_XzY0x1(HttpClient* o)
{
   int left=8192, len=0;
   BaBool value=FALSE;
   U8 c;
   while(left-- > 0 && HttpClient_readDataBuffered(o,&c,1)==1)
   {
      if(c=='\015')
      {
         if(left-- <= 0 || HttpClient_readDataBuffered(o,&c,1)!=1 || c!='\012')
            break;
         if(!len) return 0;
         if(!value) break;
         len=0;
         value=FALSE;
      }
      else
      {
         if(!value)
         {
            if(c=='\072' && len) value=TRUE;
            else if(!((c>='\060' && c<='\071') || (c>='\101' && c<='\132') ||
                      (c>='\141' && c<='\172') ||
                      (c && strchr("\041\043\044\045\046\047\052\053\055\056\136\137\140\174\176",c)))) break;
         }
         else if((c<32 && c!='\011') || c==127) break;
         len++;
      }
   }
   return updateproperty(o,E_INVALID_RESPONSE);
}


int
HttpClient_readData(HttpClient* o, void* buf, int bufSize)
{
   int size, decodetable;
   if( (size=powerdomain(o)) != 0 )
      return size;
   if(o->methodType == HttpMethod_Head || !o->size || !buf)
      return 0;
   size=0;
   if(o->chunkEncoding)
   {
      while(bufSize)
      {
         if(o->chunkSize == 0)
         {
            o->chunkSize = validether(o);
            if(o->chunkSize <= 0)
            {
               if(o->chunkSize < 0 || _XzY0x1(o))
                  return updateproperty(o, E_INVALID_RESPONSE);
               o->size=0; 
               if(HttpClient_usePersistent(o))
                  supportentry(o);
               return size;
            }
         }
         decodetable = bufSize > o->chunkSize ?  o->chunkSize : bufSize;
         decodetable = HttpClient_readDataBuffered(o, buf, decodetable);
         if(decodetable < 0)
            return  decodetable;
         size += decodetable;
         buf = (U8*)buf+decodetable;
         bufSize -= decodetable;
         o->chunkSize -= decodetable;
         baAssert(o->chunkSize >=0);
         if(!o->chunkSize)
         {
            U8 end[2];
            if(HttpClient_readDataBuffered(o,end,2)!=2 ||
               end[0]!='\015' || end[1]!='\012')
               return updateproperty(o,E_INVALID_RESPONSE);
         }
      }
      return size;
   }
   if(bufSize)
   {
      if((BaFileSize)bufSize > o->size)
         bufSize = (int)o->size;
      baAssert(bufSize);
      decodetable=HttpClient_readDataBuffered(o, buf, bufSize);
      if(decodetable < 0)
         return decodetable;
      else if( ! o->size && HttpClient_usePersistent(o))
         supportentry(o);
      size += decodetable;
   }
   return size;
}


const char*
HttpClient_getHeaderValue(HttpClient* o, const char* name)
{
   int n;
   HttpClientHeader* h = HttpClient_getHeaders(o, &n);
   if(h)
   {
      for( ; n > 0 ; h++,n--)
      {
         const char* k = HttpClientHeader_key(o,h);
         if( ! baStrCaseCmp(name, k) )
            return HttpClientHeader_val(o,h);
      }
   }
   return 0;
}


HttpClientHeader*
HttpClient_getHeaders(HttpClient* o, int* hlen)
{
   if( powerdomain(o) )
   {
      *hlen=0;
      return 0;
   }
   *hlen = o->headerLen;
   return o->headers;
}


int
HttpClient_getStatus(HttpClient* o)
{
   int s;
   if(o->httpStatus)
      return o->httpStatus;
   if( (s=powerdomain(o)) != 0 )
      return s;
   return o->httpStatus;
}



int
HttpClient_sendData(HttpClient* o, const void* data, int len)
{
   if(!len)
      return 0;
   if(o->lastError)
      return o->lastError;

   
   if( (o->chunkEncoding || o->size > 4*1024))
      supportentry(o);
   if( o->chunkEncoding )
   {
      U8 buf[2*sizeof(len)+2];
      U8* start;
      U8* end;
      int gpiolibfbank;
      end = start = buf;
      for(gpiolibfbank=(sizeof(len)-1)*8; gpiolibfbank >= 0; gpiolibfbank-=8)
      {
         baConvBin2Hex(end, (U8)((unsigned int)len >> gpiolibfbank));
         end+=2;
      }
      *end++ = '\015';
      *end = '\012';
      while(*start == '\060') start++;
      if(!SoDispCon_sendData((SoDispCon*)o, start, (int)(end-start+1)))
         if(!SoDispCon_sendData((SoDispCon*)o, data, len))
            if(!SoDispCon_sendData((SoDispCon*)o, "\015\012", 2))
               return 0;
   }
   else
   {
      if((BaFileSize)len > o->size)
         return updateproperty(o,E_TOO_MUCH_DATA);
      o->size -= len;
      if(!SoDispCon_sendData((SoDispCon*)o, data, len))
         return 0;
   }
   return o->httpStatus ?
      o->httpStatus : updateproperty(o,E_SOCKET_WRITE_FAILED);
}


#if BA_ENABLE_SHARKSSL
SharkSslCon*
HttpClient_getSharkSslCon(HttpClient* o)
{
   SharkSslCon* sc;
   if(SoDispCon_getSharkSslCon((SoDispCon*)o, &sc) != TRUE)
      return 0;
   return sc;
}
#endif

#if BA_ENABLE_SHARKSSL
SharkSslConTrust
HttpClient_trusted(HttpClient* o)
{
#if !BA_ENABLE_SHARKSSL
   return SharkSslConTrust_NotSSL;
#else
   SharkSslCon* sc;
   if(SoDispCon_getSharkSslCon((SoDispCon*)o, &sc) != TRUE)
      return SharkSslConTrust_NotSSL;
   return sc ? SharkSslCon_trusted(sc, o->host, 0) : SharkSslConTrust_NotSSL;
#endif
}
#endif

void
HttpClient_constructor(HttpClient* o,SoDisp* disp, U8 mode)
{
   memset(o, 0, sizeof(HttpClient));

   SoDispCon_constructor(
      (SoDispCon*)o, disp, signalpending);
   DynBuffer_constructor(&o->db,1024,1024,0,0);
   o->mode=mode;
   o->respManaged=TRUE;
   o->readTmo=20000;
}


void
HttpClient_close(HttpClient* o)
{
   o->headerLen=0;
   o->data=0;
   o->respManaged=TRUE;
   SoDispCon_shutdown((SoDispCon*)o);
}


void
HttpClient_destructor(HttpClient* o)
{
   if(o->host)
   {
      baFree(o->host);
      o->host = 0;
   }
   HttpClient_close(o);
   DynBuffer_destructor(&o->db); 
}


